programs.sol:
"""A strong beginning-of-text pulse, plus a small separator signal.

The initial pulse is scaled by broad token shape and remains during an
unchanged initial token run. A document-initial 'Title:' field has an extra
large colon pulse. Otherwise words/digits are near zero and standalone
punctuation, spaces and line breaks are positive. Split UTF-8 characters
are classified using their bytes, not the replacement glyph.
"""
import unicodedata as ud
import regex

READS = ()
COPULAS = frozenset('am is are was were be been being'.split())
CONJUNCTIONS = frozenset('and or but nor for yet so'.split())


def first_value(text):
    if text.startswith('<|') and text.endswith('|>'):
        return 33.0 if text == '<|im_start|>' else 23.0
    word = text.strip()
    if not word:
        if text == ' ':
            return 3.0
        if text == '\r':
            return 39.7
        if '\t' in text:
            return 23.0
        if '\n' in text:
            return 13.0 if len(text) == 1 else 7.0
        return 14.0
    if word.isdecimal():
        return 6.1 if word == '0' else 13.0
    if '\ufffd' in word:
        return 22.0
    if not any(c.isalnum() for c in word):
        w = ud.normalize('NFKC', word)
        if w == '.' and text.startswith(' '):
            return 45.5
        if w[0] in '"“”':
            return 25.0
        if w[0] in "'‘’":
            return 16.0
        if w[0] == '#':
            return 19.0
        if ud.category(w[0]) == 'Ps':
            return 16.0
        if w[0] in '.,:;!?-=' or ud.category(w[0]) == 'Pe':
            return 8.0
        return 13.0
    if regex.search(r'\p{Script=Han}', word):
        return 22.0
    if word == 'Title':
        return 20.0
    if word.lower() in COPULAS:
        return 21.0
    if word.lower() in CONJUNCTIONS:
        return 23.0
    if len(word) == 1 and word.isalpha():
        return 22.0 if text.startswith(' ') else 30.0
    if word[0].isupper():
        return 34.0 if len(word) <= 4 and not word.isupper() else 30.5
    if regex.search(r'\p{Script=Cyrillic}', word):
        return 23.0
    return 24.0 if len(word) <= 2 else 29.0


def separator_value(text, raw, tail):
    if any(c.isalnum() for c in text):
        return 0.0
    if '\ufffd' in text:
        # A partial character beginning, or a completed non-letter symbol.
        b = raw.lstrip(b' ')
        if b and b[0] >= 0xC0:
            return 1.1
        completed = (tail + raw).decode('utf-8', 'ignore')
        if completed and (completed[-1].isspace() or
                          ud.category(completed[-1])[0] in 'PS'):
            return 1.4
        return 0.0
    if text == '\x00':
        return 3.7
    w = text.strip()
    if not w:
        if text == ' ':
            return 1.85
        if not text.strip(' '):
            return 1.1
        if text == '\r':
            return 0.9
        if '\n' in text:
            if text.startswith(' '):
                return 1.05 if text.count('\n') == 1 else 1.65
            return 1.8
        if text.strip('\t') == '':
            return 1.55 if len(text) == 1 else 1.1
        return 1.65
    w = ud.normalize('NFKC', w)
    if any(c in w for c in ',、'):
        return 2.05
    if '\n' in text or '\r' in text:
        if w == '.':
            return 1.15
        return 1.75 if w in (':', ';') else 1.45
    if w in ('.', '。'):
        return 1.6
    if w in (':', ';'):
        return 1.75
    if w in ('(', '[', '{'):
        return 1.25
    if w in (')', ']', '}', '()'):
        return 1.9
    if w in ('=', '+', '&', '&&', '|', '||', '==', '==='):
        return 0.3 if w.count('=') > 1 else 1.0
    if w == '/':
        return 1.55 if text.startswith(' ') else 1.85
    if w in ('//', '/*'):
        return 1.0
    if w == '-':
        return 1.1 if text.startswith(' ') else 1.4
    if w in ('"', "'", '`'):
        return 1.2 if text.startswith(' ') else 1.5
    if ud.category(w[0]) == 'Pi':
        return 1.0
    return 1.4


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    raw = prefix.token_bytes[-1]
    doc = prefix.document_ids[-1]
    fresh = carry is None or doc != carry[0] or carry[1]
    if fresh:
        initial, unchanged, count, tail = raw, True, 0, b''
    else:
        _, _, initial, unchanged, count, tail = carry
        unchanged = unchanged and raw == initial
    if fresh or unchanged:
        value = first_value(text)
    elif count == 1 and initial == b'Title' and text == ':':
        value = 87.4
    elif text.startswith('<|') and text.endswith('|>'):
        value = 0.0
    else:
        value = separator_value(text, raw, tail)
    state = (doc, text == '<|endoftext|>', initial, unchanged,
             count + 1, (tail + raw)[-3:])
    return state, float(value)

"""Sparse lexical approximation of a 'quan'-centered negative response.

The main triggers are 全 ('all'), 泉 ('spring'), and romanized 'quan'.
Related rights, safety and completeness spellings respond less, as do a
few nearby Chinese syllables. Recent kana reduce the main response;
byte-split core characters strengthen it. Characters fire on completion.
This omits most small background and arbitrary document-start responses.
"""
import codecs
import regex

READS = ()
KANA = regex.compile(r"[\p{Hiragana}\p{Katakana}]")


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        pending, recent = b"", ""
    else:
        _, pending, recent = carry
    data = pending + prefix.token_bytes[-1]
    text, used = codecs.utf_8_decode(data, "ignore", False)
    word = text.strip()
    value = 0.0
    if word in ("全", "泉", "quan"):
        value = -5.4 if KANA.search(recent[-8:]) else -6.7
        if pending:
            value -= 1.5
    elif word == "权":
        value = -2.7
    elif word in ("權", "権"):
        value = -3.6
    elif word == "권":
        value = -1.1 if text.startswith(" ") else -2.3
    elif word in ("toàn", "quyền"):
        value = -1.1
    elif word == "大全":
        value = -4.6
    elif word == "安全":
        value = -2.2
    elif word.endswith("安全"):
        value = -1.4
    elif word in ("完全", "完全不同"):
        value = -1.2
    elif "全" in word:
        value = -0.25
    elif word.endswith(("权", "權", "権")):
        value = -0.9
    elif word in ("专", "專"):
        value = -1.5
    elif word == "専":
        value = -2.8
    elif word in ("悬", "懸"):
        value = -4.5 if pending else -3.3
    elif word in ("纯", "純", "潜", "潛", "虔"):
        value = -0.7
    elif word == "an" and recent.lower().endswith("qu"):
        value = -1.9
    elif word == "anz" and recent.lower().endswith("qu"):
        value = -5.6
    return (doc, data[used:], (recent + text)[-16:]), value

programs.haiku:
"""Negative responses to the Chinese character 全 ("all, whole, complete") and to the
words built from the same quán sound or the same "whole" / "rights" meaning:
泉 (spring), 權 / 权 (rights, power), 安全 (safety), 完全 (completely), 全新 (brand new),
and the Vietnamese and Korean words for whole and rights (toàn, quyền, 권).
The bare character 全 is the strongest response. Everything else is near zero.
The program is a lookup: each word gets a fixed guess, the typical activation the
component shows on that word in training text."""

READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1]
    if word in ("全", "泉"):
        value = -6.5  # the bare character: strongest response
    elif word in ("權", "大全"):
        value = -4.5
    elif word.endswith("全") or word in ("全新", "完全"):
        value = -1.8  # 安全, 完全, 全新 and similar: 全 as one of the two characters
    elif any(c in word for c in "权權") or word in ("권", " 권", " quyền"):
        value = -2.0  # 权 / 權 compounds (rights, power), Korean 권, Vietnamese quyền
    elif word in ("专", "專", "纯", "純", "潜", "潛", " toàn"):
        value = -1.2  # other words with a weaker response
    else:
        value = 0.0
    return None, value

programs.sol:
"""Italian-context spelling and word-piece effects.

Completed words provide a slowly fading Italian-language cue, using their
frequencies relative to other Western European languages. In that context,
short word beginnings, clitics and unfinished prefixes often contribute
negatively; the prepositions a/al and re- beginnings contribute positively.
The unfinished word is retained across token boundaries. These are spelling
rules, not an exhaustive lookup of the model's individual word pieces.
"""
import math
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
VOWELS = 'aeiouàèéìòù'
CLITICS = {'ci', 'si', 'ti', 'vi', 'mi'}
PIECES = re.compile(r'[A-Za-zÀ-ÖØ-öø-ÿ]+|[^A-Za-zÀ-ÖØ-öø-ÿ]+')


@lru_cache(65536)
def frequencies(word):
    return tuple(zipf_frequency(word, lang)
                 for lang in ('it', 'en', 'es', 'fr', 'pt', 'de'))


@lru_cache(65536)
def italian_evidence(word):
    f = frequencies(word)
    if len(word) < 2 or max(f) < 3:
        return 0.0
    return max(-4.0, min(4.0, f[0] - max(f[1:])))


def first_vowel(word):
    return next((c for c in word if c in VOWELS), '')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0.0)
    _, word, language = carry
    before = word
    for piece in PIECES.findall(text):
        if piece[0].isalpha():
            word += piece.lower()
        else:
            if word:
                language = .88 * language + italian_evidence(word)
            word = ''
    carry = (doc, word, language)
    gate = max(0.0, math.tanh(language / 6))
    if gate == 0:
        return carry, 0.0

    s = text.strip().lower()
    if not s or not s.isalpha():
        return carry, gate * .4 * ("'" in text or '’' in text)
    initial = not before or not text[0].isalpha()
    vowel = first_vowel(s)
    consonant = s[-1] not in VOWELS
    value = 0.0
    if initial:
        value = -1.05 * (not vowel)
        if len(s) <= 4:
            value -= .4 * (vowel == 'i')
            value -= 3.8 * s.startswith('ri')
            value -= 2.15 * (s.startswith('di') and len(s) > 2)
        value -= .55 * (s.startswith('s') and len(s) > 1
                          and s[1] not in VOWELS)
        value -= 2.75 * (s.startswith('s') and len(s) > 1
                           and s[1] in 'bdglmnrv')  # voiced s-clusters
        value += (2.7 * (s == 'a') + .8 * (s == 'al')
                  + 1.25 * (s == 're') - 2.15 * (s in CLITICS)
                  - 1.15 * (s == 'non') - (s in ('gi', 'qu')))
        value += 1.85 * (s.startswith('re') and len(s) <= 3)

    # Some initial syllables occupy more than one tokenizer piece.
    if word and frequencies(word)[0] < 4:
        if len(word) <= 6:
            v = first_vowel(word)
            value -= .9 * (word.startswith(('ri', 'di')) and len(word) > 1)
            if word[-1] not in VOWELS:
                value += -.8 * (v == 'i') + .4 * (v == 'e')
                value -= .45 * (v == 'o')
        value -= 2.3 * ((len(word) == 2 and word[1] == 'u')
                         or word == 'scu')
        value -= 1.5 * (not initial and word.startswith(('ri', 'di'))
                       and len(word) <= 9 and consonant)
        value -= 4.25 * (not initial and len(s) == 1 and s in VOWELS
                        and len(before) <= 4
                        and before.startswith(('ri', 'di'))
                        and before[-1] not in VOWELS)
    return carry, float(gate * value)

"""A sparse detector for operator words and agent-like word endings.

Negative values mark operator/constructor vocabulary and fragments of the
-or/-eur family, including some translated role nouns. The strength depends
on the spelling and on which part falls in the newest token. Most tokens
are near zero. 'Working directory', generators, and repeated middle dots
are small separate lexical responses. These are fitted approximations,
not a general analysis of who performs an action.
"""
import re

READS = ()

# Agent endings in Romance languages, and borrowed forms of those endings.
SUFFIX = {
    'ator': -0.25, 'ators': 0.0, 'atore': -1.9, 'atori': -2.3,
    'ador': -1.3, 'adores': -0.9, 'adora': -0.3,
    'edor': -1.45, 'idor': -1.25, 'itor': -0.55, 'utor': -0.2,
    'otor': -1.5, 'ktor': -1.05, 'tor': -1.0,
    'ateur': -1.9, 'ateurs': -1.0, 'iteur': -1.7,
}
OR_ENDINGS = {'or', 'ors', 'ore', 'ores', 'ora', 'ori',
              'oria', 'ory', 'orem', 'oren'}
ROLE_ENDINGS = OR_ENDINGS | SUFFIX.keys() | {'eur', 'eurs', 'ur', 'urs'}


def response(text, left):
    s = text.lower()
    l = left.lower()
    word = s.strip(' _.\t')
    if word in ('operator', 'operators'):
        if l.endswith('\\'):
            return -0.06  # LaTeX's \\operatorname, not an operator noun.
        if l.endswith('::') or re.search(
            r'\b(bool|void|ostream|istream|overloaded)\s*$', l
        ):
            return -3.7
        return -0.9 if word == 'operators' else -1.8
    if (word in ('constructor', 'constructors')
            or (s == 'structor' and l.endswith('con'))):
        return -1.2
    if word == 'directory':
        return 0.69 if l.endswith('working') else 0.0
    if word == 'generator':
        return 0.37
    if s == '··' and l.endswith('·'):
        return -1.23

    # Translated operators, constructors, handlers, and merchants.
    if s in ('符', '子') and l.endswith(('运算', '運算')):
        return -6.8
    if s in ('函数', '函數') and l.endswith(('构造', '構造')):
        return -4.4
    if s in ('程序', '程式') and l.endswith(('处理', '處理')):
        return -4.6
    if s == '程式' and l.endswith('用'):
        return -1.3
    if s == '商' and l.endswith((
        '经营', '經營', '分销', '分銷',
        '经销', '經銷', '供应', '供應',
    )):
        return -3.6
    if s == '자' and l.endswith(('생성', '작성', '접종')):
        return -3.9
    if s == 'タ' and l.endswith('トラク'):
        return -3.0

    if s == 'tor' and left.endswith('C'):
        return -3.5  # Ctor is a programming abbreviation for constructor.
    if s in ROLE_ENDINGS:
        if l.endswith(('oper', 'опер')):
            return -5.2
        if l.endswith(('construct', 'construc', 'construt')):
            return -6.2
    if s in OR_ENDINGS:
        if not l.endswith(('t', 'd')):
            return -0.04
        # English -ors is weak; Romance plurals -ores/-ori are stronger.
        if s == 'ors':
            return -1.7 if l.endswith('ot') else -0.3
        if s == 'ores':
            return -3.0 if l.endswith('d') else -2.4
        if s in ('ori', 'oren', 'orem'):
            return -2.3 if l.endswith('t') else -0.2
        if s == 'ore':
            return -3.6 if l.endswith('at') else -1.4
        if s == 'ora':
            return -4.8 if l.endswith('id') else -1.4
        if s in ('oria', 'ory'):
            return -0.5
        # Short -or is stronger when attached to a vowel + t/d stem.
        if re.search(r'[aeiou][td]$', l):
            return -2.3
        return -1.1
    if s in ('eur', 'eurs'):
        return -3.7 if l.endswith('t') else -0.35
    if s in ('ur', 'urs', 'ure'):
        # Complete the French -teur, -seur, -neur, -reur, -geur endings.
        if l.endswith('te'):
            return -2.0 if s == 'ure' else -3.2
        if l.endswith(('se', 'ge')):
            return -1.7
        if l.endswith(('ne', 're')):
            return -1.0
        return -0.25 if l.endswith('e') else 0.0
    if s in ('res', 'ρ') and l.endswith(('to', 'tó', 'το', 'τό')):
        return -3.4
    if s in ('ör', 'ør', 'oir'):
        return -1.8 if l.endswith(('t', 'd', 's')) else 0.0
    if s in SUFFIX:
        return SUFFIX[s]
    if s in ('атор', 'тор', 'ора'):
        return -1.4
    if s == 'ор' and l.endswith('т'):
        return -0.9
    if s in ('use', 'uses') and l.endswith('e'):
        return -0.45
    if s in ('rice', 'rices') and l.endswith('t'):
        return -0.6
    if s in ('a', 'e', 'i', 's', 'ы', 'а', 'ов', 'у'):
        if re.search(r'(?:[td]or[ei]?|тор[ао]?)$', l):
            return -1.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == doc else b''
    # Joining bytes preserves characters split across tokenizer pieces.
    left = history.decode('utf-8', errors='replace')
    text = prefix.token_strings[-1]
    value = response(text, left)
    history = (history + prefix.token_bytes[-1])[-512:]
    return (doc, history), value

programs.haiku:
"""Component layers.1.mlp.down_proj:260: a detector for agent nouns (doers and makers).

What it does: the component is silent on almost every token. It goes clearly negative on the
last piece of a word that names a doer, when that piece is split off from its stem:
French "compt|eur", "fondat|eur", "capt|eur"; Spanish "corred|ores", "oper|adora";
Italian "creat|ore", "Imper|ator"; Russian "опер|атор" and "-тор" endings; Turkish and
Scandinavian "akt|ör", "direkt|ør"; Latin-style "-tor". It is also negative on the English code
and prose words "operator", "constructor", "decorator" (with or without a leading space). The
strongest response is to "-eur" and "-ador"; the bare endings "-or", "-ur", "-ore", "-ors" are
weaker. It is mildly positive on " directory", as in tool text "[Current working directory: ...]".
Everything else is predicted as 0.

The rule reads only the current token, so it is causal. The values are the typical activation
of each ending, fitted on training text.
"""

READS = ()

# Word-final pieces that complete a foreign agent noun, grouped by ending.
EUR = {"eur": -1.9, "eurs": -1.6, "ateur": -2.4, "iteur": -2.0, "ateurs": -1.0}
ADOR = {"ador": -1.8, "adores": -1.9, "adora": -1.5, "atore": -1.8, "atori": -2.0, "ADOR": -2.5, "edor": -1.2}
RU = {"атор": -1.75, "тор": -1.35, "otor": -1.3, "ора": -0.8, "ор": -0.2}
TOR = {"tor": -1.15, " tor": -0.6, " тор": -0.3, "itor": -0.6, "ator": -0.25, "ators": -0.3,
       "autor": -0.5, "uator": -0.3, "orio": -0.4, "rice": -0.6}
ORES = {"ores": -0.55, "urs": -0.55, "ore": -0.35, "or": -0.25, "ors": -0.2, "ur": -0.27,
        "ör": -0.4, "ori": -0.4, "oren": -0.8, "ORE": -0.8, "OR": -0.3, "ORS": -0.4,
        "uteur": -0.4}
# English and code words for a doer or maker.
OPER = {" operator": -1.8, " operators": -1.1, "operator": -1.25, "Operator": -1.7, " Operator": -1.7,
        "_operator": -2.1, "-operator": -1.9, " Operators": -1.3, " constructor": -1.3,
        " Constructor": -1.4, "Constructor": -0.35, " decorator": -0.8, ".constructor": -1.8}
# A few other pieces with the same sign, and the positive " directory".
OTHER = {"자": -0.75, "符": -1.8, "程序": -1.0, "函数": -0.7, " directory": 0.45, " Directory": 0.8}

TABLE = {}
for group in (EUR, ADOR, RU, TOR, ORES, OPER, OTHER):
    TABLE.update(group)


def step(carry, prefix, upstream):
    return carry, float(TABLE.get(prefix.token_strings[-1], 0.0))

"""Layer 1, MLP down-projection component 261: an "m-word" detector.

What it does: the component goes negative on words that contain the letter m
in a way the model can see: (1) a word that starts with m or M (may, most, many,
much, make, model, main, match, min, max, ...), on its first and later pieces;
(2) the later pieces of a longer word once an earlier piece already contained an m
(Bismar|ck, therm|op, em|ilio). Strongest for the first piece of an m-word (about -1),
weaker for later pieces; the m-like letters µ, μ and Cyrillic м count as m. It is
mildly negative on the pronouns my / me, and very negative (about -4.5) on the
double middle-dot token "··". Everything else is essentially 0.

Word boundaries come from the text: a token that starts with a space, newline or
punctuation starts a new word, a document change starts a new word, and a token
that follows a letter continues the word. The program carries the current word's
first letter, piece number and whether an earlier piece had an m.
"""

READS = ()

M_LETTERS = set("mMµμмМ")                      # m, M, micro sign, Greek mu, Cyrillic em
PIECE_LEVEL = (-0.94, -1.07, -0.56, -0.25)    # m-initial word, by piece index (0 = first token)
CONTINUATION_LEVEL = -0.5                     # later piece of a word whose earlier piece had an m
PRONOUN_LEVEL = -0.3                          # my, me, myself
DOUBLE_DOT = "··"
DOUBLE_DOT_LEVEL = -4.5


def first_letter(text):
    for ch in text:
        if ch.isalpha():
            return ch
    return ""


def has_m(text):
    return any(ch in M_LETTERS for ch in text)


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None:
        prev_doc, letter, piece, prev_alnum, m_before = None, "", 0, False, False
    else:
        prev_doc, letter, piece, prev_alnum, m_before = carry
    starts_word = (
        doc != prev_doc
        or not prev_alnum
        or (not text[:1].isalnum() and text[:1] != "'")
    )
    if starts_word:
        letter, piece, m_before = first_letter(text), 0, False
    else:
        piece += 1
    ends_alnum = text[-1:].isalnum()
    new_carry = (doc, letter, piece, ends_alnum, m_before or has_m(text))

    if text == DOUBLE_DOT:
        value = DOUBLE_DOT_LEVEL
    elif letter in M_LETTERS:
        value = PIECE_LEVEL[min(piece, len(PIECE_LEVEL) - 1)]
        if piece == 0 and text.strip().lower() in ("my", "me", "myself"):
            value = PRONOUN_LEVEL
    elif m_before:
        value = CONTINUATION_LEVEL
    else:
        value = 0.0
    return new_carry, float(value)

programs.sol:
"""Local spelling fragments, dominated by 'eer' and its token completions.

Completing e + er gives a large negative response; familiar whole-word
families have their own, usually smaller, strengths. Doubled r (as in
Error) is excluded. Short fragments ending in Japanese ア are negative,
more strongly after an e-vowel character; Korean 어 is weakly negative.
Small positive responses mark e + e and e + a completions.
Only the previous token and a few recent bytes are retained, with a reset
at document boundaries. Unmodelled background variation stays near zero.
"""
import re
from anyascii import anyascii

READS = ()


def response(previous, text, previous_character):
