        value = -2.7
    elif re.fullmatch(r'career(s|ed|ing)?', word):
        value = -0.75
    elif re.fullmatch(r'(beer|deer)s?', word):
        value = -1.5
    elif re.fullmatch(r'peer(s|ed|ing)?', word):
