        _, previous, recent = carry
    text = prefix.token_strings[-1]
    last_character = recent.decode('utf-8', errors='ignore')[-1:]
    value = response(previous, text, last_character)
    recent = (recent + prefix.token_bytes[-1])[-16:]
    return (doc, text, recent), value

