"""Negative response on words whose spelling ends in 'eer' (steer, cheer, peer, engineer), read as the
long-e + r sound. Strongest on steer/cheer/sneer-type words, moderate on engineer/peer, weak on
beer/deer/queer, mild on career, and none on error, pioneer, volunteer or cheerful. The katakana
syllable ア (and ニア, 'near'), which stands for the same 'air/ear' sound, also responds."""
READS = ()

STRONG = {"steer", "steers", "steering", "steered", "cheer", "cheers", "cheering", "sneer", "sneered", "veer", "veers", "seer", "seers", "sheer"}
MEDIUM = {"engineer", "engineers", "engineering", "engineered", "peer", "peers", "peered", "mountaineer", "mountaineers"}
WEAK = {"beer", "beers", "deer", "queer", "leer", "meer"}
MILD = {"career", "careers"}
ZERO = {"pioneer", "pioneers", "pioneering", "pioneered", "volunteer", "volunteers", "volunteered",
        "cheerful", "cheerfully", "cheery", "cheeriest", "eerie"}

def step(carry, prefix, upstream):
    word = carry or ""
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        word = ""
    piece = prefix.token_strings[-1]
    text = (word + piece).lower()
    new = ""
    for ch in reversed(text):
        if not ch.isalpha():
            break
        new = ch + new
    value = 0.0
    if "eer" in new and "eer" not in word and "eerr" not in new and new not in ZERO:
        value = -3.0
        if new in STRONG:
            value = -6.0
        elif new in WEAK:
            value = -1.5
        elif new in MILD:
            value = -0.7
    if piece in ("ア", "ニア"):
        value = -2.6
    return new, value

