"""Approximate a closing-delimiter signal using punctuation and shallow syntax.

Isolated closing marks get positive values; spaces, line breaks and bundled
sentence punctuation usually weaken them. Calls, nesting and array indexing
increase the response. A single quote inside square brackets is especially
strong: a rough proxy for quoted list/index items, without parsing strings.

The bracket stack records whether an opener touches an ASCII identifier or
another closing bracket. It is only a code/prose heuristic, not a language
parser. Ordinary words get zero; state resets at each document boundary.
"""

READS = ()

CLOSERS = {
    ')': 1.15,
    ']': 1.26,
    '}': 0.97,
    "'": 1.07,
    '"': 1.10,
    '`': 0.61,
    '>': 0.65,
    '$': 0.55,
    '%': 0.24,
    '()': 2.09,
    '[]': 0.96,
    '{}': 0.68,
    "')": 1.91,
    '")': 1.11,
    "']": 2.99,
    '"]': 1.87,
    '))': 0.84,
    '())': 1.37,
    '})': 0.59,
    '])': 1.09,
    '}}': 0.47,
    '$$': 0.49,
    '\\"': 0.76,
    "\\'": 0.38,
    '’': 0.30,
    '”': 0.36,
    '）': 0.41,
}

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        carry = (doc, '', [])
    _, text, brackets = carry
    s = prefix.token_strings[-1]
    t = s.strip()
    previous_token = '' if first else prefix.token_strings[-2]
    previous_char = text[-1:] or ' '
    parentheses = [b for b in brackets if b[0] == '(']
    squares = [b for b in brackets if b[0] == '[']
    depth = len(parentheses)
    call = bool(parentheses and parentheses[-1][1])
    index = bool(squares and squares[-1][1])
    age = prefix.position - parentheses[-1][2] if depth else 1000
    operators = '=' in text[-100:] or ';' in text[-100:]
    indented = '\t' in text.rsplit('\n', 1)[-1]

    value = CLOSERS.get(t, 0.0)
    if s == ')':
        if call:
            value = 1.8 + 0.6 * (depth > 1) + 0.5 * indented
        elif operators and age <= 16:
            value = 1.4
        elif depth > 1:
            value = 1.6
        else:
            value = 0.75
    elif s == ']':
        if index:
            value = 2.0 + 0.9 * operators
            if previous_char.isdigit():
                value += 0.3 + 0.5 * operators
        else:
            value = 0.6 if previous_char.isdigit() else 1.25
    elif s == "'" and squares:
        value = 4.2
    elif s == '()':
        value = 2.8 if depth else 1.85
    elif s == ' =':
        if len(previous_token.strip()) <= 2:
            value = 0.43 if indented else 0.11
        else:
            value = 0.57 if previous_token.startswith(' ') else 0.37
    elif s == ' :=':
        value = 0.64
    elif t in CLOSERS:
        if s.startswith((' ', '\t')):
            if t in (')', ']', '}'):
                value *= 0.5
            elif t == '()':
                value = 1.55
            elif t == '[]':
                value = 0.89
            else:
                value *= 0.08
        if '\n' in s or '\r' in s:
            value *= 0.22
            if s.count('\n') > 1:
                value *= 0.4
    elif t and not any(c.isalnum() for c in t):
        if any(c in t for c in ',.;:'):
            value = 0.03
        elif t.startswith('()'):
            value = 0.65
        elif t.startswith((')', ']', '}')) and t[-1] in '\\$({]}':
            value = 0.4
        elif t == '{':
            value = 0.16
        elif t in ('__', '**', '###'):
            value = 0.22

    # Keep a short text tail and raw bracket nesting with attachment flags.
    for ch in s:
        before = text[-1:] or ' '
        if ch in '([{':
            attached = before.isascii() and (
                before.isalnum() or before in '_)]'
            )
            brackets.append((ch, attached, prefix.position))
            brackets = brackets[-32:]
        elif ch in ')]}':
            opening = {')': '(', ']': '[', '}': '{'}[ch]
            for k in range(len(brackets) - 1, -1, -1):
                if brackets[k][0] == opening:
                    del brackets[k:]
                    break
        text = (text + ch)[-200:]
    if first:
        value = 0.0
    return (doc, text, brackets), float(value)

