"""Closing-delimiter detector: fires on the token that closes a bracket, a quotation or
an empty pair of parentheses in code or text, most strongly when the opener is only a
token or two back."""
READS = ()

BASE = {")": 1.2, "]": 1.1, "}": 1.0, "'": 1.3, '"': 1.2, '\\"': 0.8}
OPENER = {")": "(", "]": "[", "}": "{", "'": "'", '"': '"', '\\"': '"'}
WHOLE = {"()": 2.2, " ()": 1.6, "']": 3.5, "')": 1.9, '}"': 2.1, "`": 0.6, ">": 0.6, "$": 0.5, " =": 0.3}

def step(carry, prefix, upstream):
    t = prefix.position
    tok = prefix.token_strings[-1]
    last = carry if carry is not None else {}
    if t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        last = {}
    value = 0.0
    if tok in BASE:
        k = last.get(OPENER[tok])
        if k is None:
            value = 0.3 * BASE[tok]
        else:
            d = t - k
            value = BASE[tok] * (1.5 if d <= 2 else 1.0 if d <= 5 else 0.7)
    elif tok in WHOLE:
        value = WHOLE[tok]
    if "\n" in tok:
        last = {}
    for ch in "([{'\"":
        if ch in tok:
            last = dict(last); last[ch] = t
    return last, float(value)

programs.sol:
"""A local detector for similes, analogies, and ways of describing things.

Comparative 'like' is distinguished from liking something. Strong negative
responses mark explicit comparisons; weaker ones mark their grammatical links.
Strengths are coarse training estimates, not token-ID lookups. The weak
token-specific remainder is left out. A bounded byte suffix handles split
words and resets at each document.
"""
import re
from functools import lru_cache
import wordnet

READS = ()
VALUES = {
    'a_sense': -1.3,
    'analogy_word': -3.3,
    'approximation': -0.8,
    'as_article': -0.4,
    'as_chinese': -0.8,
    'as_if': -3.6,
    'as_other': -0.2,
    'comparison_as': -1.9,
    'correspond_to': -1.3,
    'foreign_comparison': -0.4,
    'form_of': -0.8,
    'in_terms': -1.1,
    'kind_of': -1.1,
    'like_appearance': -1.2,
    'like_article': -2.1,
    'like_chinese': -1.7,
    'like_comparison': -4.3,
    'like_description': -1.3,
    'like_preference': 0.3,
    'related_to': -0.6,
    'resemble': -2.9,
    'role_as': -0.9,
    'seems_chinese': -2.9,
    'sense_of': -1.2,
    'similar_chinese': -4.6,
    'similar_to': -3.9,
    'simile_article': -1.3,
    'simile_chinese': -6.3,
    'simile_of': -4.6,
    'sort_of': -3.5,
    'think_as': -3.5,
}
COPULAS = set('is are was were be been being s m re'.split())
PERCEPTION = {'look', 'sound', 'feel', 'seem'}
MANNER = {'act', 'behave', 'flow', 'cling', 'stand', 'read', 'hold'}
INTERPRET = {'treat', 'view', 'model', 'act', 'behave'}
ROLE = {'see', 'regard', 'consider', 'interpret', 'represent', 'serve', 'feel'}
IMAGE = ('图像', '圖像', '影像', '画像', '畫像', '摄像', '攝像',
         '录像', '錄像', '头像', '頭像', '偶像', '肖像', '塑像', '佛像')


@lru_cache(maxsize=8192)
def forms(word):
    return frozenset(wordnet.base_forms(word)) | {word}


def category(old, text, last):
    new = text[len(old):].strip()
    if not new:
        return 'other'
    if '像' in new and not text.endswith(IMAGE):
        if text.endswith(('就好像', '就好像是')):
            return 'simile_chinese'
        if text.endswith(('好像', '好像是')):
            return 'seems_chinese'
        return 'simile_chinese' if '就像' in new else 'like_chinese'
    if text.endswith((
        '仿佛', '彷彿', '彷佛', '犹如', '猶如', '宛如', '如同', '宛若', '好比'
    )):
        return 'simile_chinese'
    if (text.endswith(('类似于', '類似於', '相当于', '相當於'))
            or (new == '似' and old.endswith(('类', '類')))):
        return 'similar_chinese'
    if new in ('如', '似') or new.endswith('正如'):
        return 'as_chinese'
    matches = list(re.finditer(r'[^\W\d_]+', text))
    if not matches or not text[-1:].isalpha():
        return 'other'
    words = [m.group() for m in matches]
    w = words[-1]
    p = words[-2] if len(words)>1 else ''
    q = words[-3] if len(words)>2 else ''
    recent = words[-7:-1]
    if len(matches)>1:
        gap = text[matches[-2].end():matches[-1].start()]
        if gap.strip() or '\n' in gap:
            p = ''
    if w == 'like':
        if p in ('would', 'should', 'could', 'd', 't', 'also', 'really', 'you'):
            return 'like_preference'
        if p == 'much' and 'would' in recent:
            return 'like_preference'
        if p in COPULAS and any(x in ('what', 'how') for x in recent):
            return 'like_description'
        if p in COPULAS or p in ('more', 'much', 'almost', 'nearly', 'bit', 'kinda'):
            return 'like_comparison'
        if forms(p) & MANNER or p == 'exactly':
            return 'like_comparison'
        if forms(p) & PERCEPTION or p in ('something', 'anything', 'just', 'of'):
            return 'like_appearance'
        return 'like_other'
    if w in ('if', 'though') and p == 'as':
        return 'as_if' if q != 'same' else 'other'
    if w == 'to':
        if forms(p) & {
            'similar', 'equivalent', 'akin', 'analogous',
            'liken', 'analogy', 'resemblance'
        }:
            return 'similar_to'
        if forms(p) & {'correspond', 'comparable', 'identical', 'isomorphic'}:
            return 'correspond_to'
        if forms(p) & {'related', 'relate', 'proportional'}:
            return 'related_to'
    if w == 'of':
        if p == 'sort':
            return 'simile_of' if q == 'a' else 'sort_of'
        if p == 'kind':
            return 'simile_of' if q in COPULAS or q in ('a', 'some') else 'kind_of'
        if p in ('equivalent', 'analogue', 'reminiscent'):
            return 'simile_of'
        if p == 'sense' or 'think' in forms(p):
            return 'sense_of'
        if p in ('form', 'type', 'terms', 'manner', 'version'):
            return 'form_of'
    if w == 'as':
        if 'of' in recent and any('think' in forms(x) for x in recent):
            return 'think_as'
        if any(forms(x) & INTERPRET for x in recent[-4:]) or p == 'same':
            return 'comparison_as'
        if any(forms(x) & ROLE for x in recent[-3:]) or p in COPULAS:
            return 'role_as'
        return 'as_other'
    if w in ('a', 'an', 'the'):
        if p == 'like':
            return 'like_article' if w != 'the' else 'other'
        if p == 'as':
            return 'as_article' if w != 'the' else 'other'
        if last in ('resemble', 'simile_of', 'sort_of'):
            return 'simile_article'
        return 'other'
    if 'resemble' in forms(w):
        return 'resemble'
    if w in (
        'analogy', 'analogies', 'metaphor', 'metaphors',
        'metaphorical', 'metaphorically', 'simile'
    ):
        return 'analogy_word'
    if w in ('basically', 'essentially', 'literally', 'almost', 'nearly'):
        return 'approximation'
    if w == 'terms' and p == 'in':
        return 'in_terms'
    if w == 'sense' and p in ('a', 'the'):
        return 'a_sense'
    if w in ('как', 'wie', 'comme', 'como', 'như', 'gibi'):
        return 'foreign_comparison'
    return 'other'


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, b'', 'other')
    _, tail, last = carry
    raw = prefix.token_bytes[-1]
    old = tail.decode('utf-8', errors='ignore').lower()
    text = (tail + raw).decode('utf-8', errors='ignore').lower()
    kind = category(old, text, last)
    state = (doc, (tail + raw)[-120:], kind)
    return state, float(VALUES.get(kind, 0.0))

"""A date-prefix detector with a few separate formatting responses.

At the second digit of 19 or 20, predict a generally negative value, strengthened
by English date cues and weakened by dense numeric surroundings. The pairs
30 and 31 also give negative contributions. Inside longer numbers, 19/20
become small positive responses and 30/31 remain weakly negative.
Paired middle dots, an initial 'Title:', parenthesized c/C (especially in
copyright notices), and Go's '%w' format have separate positive responses. This is a compact
approximation; it does not explain the component's other lexical responses.
"""
import calendar
import re

READS = ()
MONTH = re.compile(
    r'\b(' + '|'.join(calendar.month_name[1:])
    + r')(?:\s+\d{1,2}(?:st|nd|rd|th)?[,]?)?\W*$', re.I
)
WORD = re.compile(r'([^\W\d_]+)[\s(]*$')


def year_prefix(pair, context, digits):
    """Use the number's left boundary, date cues, and recent digit density."""
    match = WORD.search(context)
    word = match[1].lower() if match else ''
    separator = context[-1:]
    # Fitted shared corrections, rather than a table of individual tokens.
    value = -0.590 if pair == '19' else -0.286
    if separator == ' ':
        value -= 0.167
    elif separator == '(':
        value -= 0.456
    elif separator in ('\r', '\n'):
        value -= 0.092
    if word in ('in', 'since', 'during'):
        value -= 0.512
    if word in ('the', 'early', 'late', 'mid'):
        value -= 0.436
    if MONTH.search(context):
        value -= 0.351
    if word in ('born', 'died'):
        value -= 0.608
    if word in ('from', 'until', 'before', 'after', 'between'):
        value -= 0.308
    value += 0.022 * max(0, digits[-16:].count('1') - 1)
    value += 0.407 * digits.count('1') / max(1, len(digits))
    if separator.isalpha():
        value -= 0.181
    if separator and separator in '$=+*^[{':
        value += 0.271
    return max(-2.0, min(0.5, value))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        text, run, context, digits = '', '', '', ''
    else:
        _, text, run, context, digits = carry
    token = prefix.token_strings[-1]
    is_digit = len(token) == 1 and token in '0123456789'
    value = 0.0
    if is_digit:
        pair = run[-1:] + token
        if len(run) == 1:
            if pair in ('19', '20'):
                value = year_prefix(pair, context, digits)
            elif pair == '30':
                value = -0.62
            elif pair == '31':
                value = -0.40
        elif len(run) > 1:
            if pair == '19':
                value = 0.12
            elif pair == '20':
                value = 0.33
            elif pair == '30':
                value = -0.26
            elif pair == '31':
                value = -0.12
        if not run:
            context = text
        run += token
    else:
        run = ''
        if token == '··':
            value = 1.09
        elif token == ':' and text == 'Title':
            value = 16.399
        elif token == 'w' and text.endswith('%'):
            value = 3.0
        elif token == ')' and re.search(r'\([cC]$', text):
            value = 0.47
            if re.search(r'copyright\s*\([cC]$', text, re.I):
                value = 11.8 if text.endswith(' (c') else 5.2
    text = (text + token)[-160:]
    digits = (digits + ('1' if is_digit else '0'))[-128:]
    return (doc, text, run, context, digits), float(value)

