"""Approximate spelling-sensitive r/l responses; most positions receive zero.

Control words, central, some r/l names, and short r-l fragments are positive.
The current word is carried across token boundaries. Short l-bearing Hungarian
fragments are negative, especially beside long vowels; dictionary frequencies
provide a recent-language cue. Small additional rules cover katakana ru and
Chinese central/control forms. Response levels are empirical approximations,
not a reconstruction of all the component's contextual variation.
"""
import re
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency as frequency

READS = ()
LONG_VOWELS = 'áéíóőúű'


@lru_cache(maxsize=8192)
def hungarian_word(word):
    if len(word) < 3:
        return False
    hu = frequency(word, 'hu')
    accented = any(c in word for c in 'áéíóöőúüű')
    return hu > (4.0 if accented else 5.5) and hu > 1.5 + max(
        frequency(word, lang)
        for lang in ('en', 'de', 'es', 'pt', 'tr', 'pl', 'cs', 'sk')
    )


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
