    # Short r-l syllables differ from ordinary complete words such as "role".
    if attached and re.fullmatch(r'a?r[aeiou]?ll?', folded):
        value = 2.2 if frequency(folded, 'en') < 3.5 else 0.7
        if 'll' in folded and frequency(folded, 'en') < 3.5:
            value = 2.6
        if folded in ('rl', 'rel'):
            value = 0.5
    if (attached and token[0].islower()
            and re.fullmatch(
                r'(?:[aeiou]|c)?l(?:l|e|es|s|ed|ing)?', folded)
            and re.search(r'r[aeiouc]?$', before)
            and frequency(before, 'en') < 4.5
            and tail[-1:] not in LONG_VOWELS):
        value = 1.4
        if folded in ('ll', 'all'):
            value = 2.6
        if frequency(whole, 'en') > 4.5:
            value *= 0.4

    # Related spellings and translations of control, including code names.
    if re.search(r'[ck]ontroll?(?:e|s|es)?$', whole):
        value = 2.8 if folded == 'controle' else 2.0
        if fragment == 'control' and token[:1].isupper():
            value = 3.0
        if folded == 'control' and token[:1].isspace():
            value = 1.2
        if previous.strip().lower() in ('to', 'can', 'will', 'would', 'could'):
            value *= 0.5
        if attached and tail and 'control' in folded:
            value = 3.5
        if attached and tail and not folded.startswith('control'):
            value = 4.5
        if token.startswith(('-', '_')) and folded.startswith('control'):
            value = 3.5
        if before.lower().endswith('cache'):
            value = 7.5
    if re.fullmatch(r'(?:c?trl|ctl)', folded):
        value = 3.0
        if folded == 'trl' and before.endswith('c'):
            value = 4.5
    if token.strip() == 'RL':
        value = 3.5
    if re.search(r'(?:[cz]|ts)entral(?:e|s|es)?$', whole):
        value = 2.0
        if fragment == 'central' and token.strip()[:1].isupper():
            value = 2.6
        if folded == 'entral':
            value = 3.0
        if folded in ('al', 'als'):
            value = 4.5
        if previous.strip().lower() == 'grand':
            value = 5.5
    if folded in ('circle', 'circles'):
        value = 1.5 if token.strip()[:1].isupper() else 0.4
    if re.fullmatch(r'[kc]ar(?:o)?l[oa]?', whole):
        value = 2.4 if folded == whole else 3.5
    if folded == 'earl':
        value = 1.1
    if whole.startswith('electrol'):
        value = 4.8 if folded == 'rol' else 0.5

    # Hungarian liquid-bearing subwords, not arbitrary accented European words.
    if hu and 'l' in fragment and len(fragment) <= 5:
        if attached or any(c in fragment for c in LONG_VOWELS):
            value = -1.8
            if (tail and tail[-1] in LONG_VOWELS
                    and fragment in ('l', 'll', 'ls', 'lt', 'ld', 'rol', 'ml')):
                value = -5.3
            if fragment == 'alk' and tail.endswith('ll'):
                value = -5.5
            if re.search(r'[áéíóőúű]l$', fragment):
                value = -4.0
            if vowel_l:
                value = -6.5
            if fragment == 'áll':
                value = -5.5
    if token == 'ル':
        value = 2.5 if previous.endswith('ラ') else 0.6
    if token == '中央':
        value = 0.9
    if token in ('控制', '控'):
        value = 1.2
    if token == '件' and previous.endswith('控'):
        value = 4.8

    match = re.search(r'[^\W\d_]+$', word)
    tail = match.group()[-32:] if match else ''
    return (doc, token, tail, hu), value

"""A sparse text-level approximation of English mathematical exposition.

It responds positively to headings, TeX display/reference markup, and phrases
that start a calculation ("let me try", "in terms of", "we need to"). It
responds negatively to references to formal statements and "the present" work.
Recent math/code cues adjust several phrase responses. Other tokens receive a
small baseline. The 384-character buffer resets at each document boundary.
"""
import re

READS = ()
FORMAL = set('statement assertion claim theorem lemma proposition formula '
             'expression equality identity relation'.split())
AIMS = set('aim objective requirement'.split())
EXPLORE = set('define find consider compute visualize start'.split())


def response(token, before):
    word = token.strip()
    low = word.lower()
    text = before.lower()
    prev = re.search(r"([a-z]+(?:['’]s)?)\W*$", text[-90:])
    prev = prev[1] if prev else ''
    ref = prev in {'the', 'this', 'that', 'our', 'my', 'given', 'above',
                   'following', 'problem', 'second'}
    code = bool(re.search(
        r'<tool_|</tool_|\b(?:def |pytest|bash|test files)', text))
    math = not code and bool(re.search(
        r'[=^²³√∑∫]|\\(?:frac|sqrt)|\b(?:equation|integer|triangle|'
        r'angle|polynomial|theorem|matrix|factor|prime)\b', text))
    noun = low[:-1] if low.endswith('s') else low

    # Section headings and expository labels.
    if word and set(word) == {'#'} and 2 <= len(word) <= 6:
        if before.endswith('#'):
            return 0.001
        if len(word) == 3 and re.search(r'\d+k? views\s*$', text):
            return 5.787
        if re.search(r'\d+\.\s*$', before):
            return 1.805
        if len(word) == 3:
            dated = re.search(r'\b(?:19|20)\d\d\s*$', before)
            return 2.006 if dated else 0.844
        return 0.376
    if token.isspace() and '\n\n' in token:
        if re.search(r'\d+k? views\s*$', text):
            return 2.047
        if prev == 'references':
            return 0.327
    if low == 'links' and prev == 'external':
        return 2.632
    if low == 'explanation' and (not token.startswith(' ') or
                                 '\n' in before[-30:]):
        numbered = re.search(r'question \d+\s*$', text)
        return 2.523 if numbered else 0.733
    if word.startswith(':') or word.startswith('):'):
        if prev == 'explanation':
            return 2.951
        if prev in {'question', 'answer', 'solution'}:
            return 0.325

    # TeX layout and cross-references.
    if low == 'style' and before.endswith('\\display'):
        return 2.314
    if low == 'align' and re.search(r'\\(?:begin|end)\{$', before):
        return 3.821
    if word == '{':
        if re.search(r'\\(?:label|ref|eqref)$', before):
            return 1.676
        if re.search(r'\\(?:begin|end)$', before):
            return 0.464
    if low == 'proof' and re.search(r'\\end\{(?:sub)?$', before):
        return -2.175
    if word == 'The' and re.search(r'proof of\s*$', text):
        return -2.787

    # Phrases introducing a calculation or an attempted solution.
    if word in {"'s", '’s'} and prev == 'let':
        return 1.363 if math else 0.59
    if re.search(r"\blet(?: me|['’]s)\s*$", text):
        if low == 'try':
            return 2.549
        if low in {'see', 'check'}:
            return 0.582 if code else 1.386
        if low in EXPLORE:
            return 0.471
    if low == 'to' and prev == 'need':
        return 0.576 if math else 0.003
    if low == 'need' and prev in {'we', 'i'}:
        return 0.387 if math else 0.089
    if low in {'check', 'verify', 'find', 'compute'} and prev == 'to':
        return 0.594 if math else 0.041
    if low == 'terms' and prev == 'like':
        return 2.427
    if ((low == 'terms' and prev == 'in') or
            (low == 'of' and text.endswith('in terms'))):
        return 1.362 if math else 0.393
    if low == 'general' and prev in {'in', 'the', 'a'}:
        return 1.518 if math else 0.387
    if low == 'possible' and (ref or word == 'Possible' or
            prev in {'so', 'a', 'one', 'all', 'only', 'consider'}):
        return 0.965 if math else 0.421
    # Backward references to a study or a formal object.
    if low == 'present' and prev == 'the':
        return -0.84
    if noun in FORMAL:
        return -0.408 if math else -0.112
    if low == 'proof' and ref:
        return -0.955
    if noun in AIMS and ref:
        return -0.594
    if low == 'of' and prev in {'result', 'objective', 'aim'}:
        return -0.485
    return 0.001


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = response(token, before)
    return (doc, (before + token)[-384:]), float(value)

programs.haiku:
"""Heuristic readout of layers.1.mlp.down_proj:270 (v11).

What it does, in plain terms: this MLP output direction is quiet almost everywhere
(typical |activation| ~0.05) and spikes on a few kinds of word:
  * markdown heading marks (##, ###, ...), strongest when they start inline after a sentence;
  * reference boilerplate and layout cues: "External links", "see below/figure", "related article",
    and LaTeX label/style words such as \\displaystyle, \\ref{, \\label{, align;
  * self-talk in worked solutions: the verb after "Let me" / "Let's" / "we need to" (try, see, check,
    verify, ...), and the "'s" in "Let's";
  * "in terms of", "prior art", "in general" (weak positive);
  * negative on abstract maths-claim nouns after "the" or "left/right/both" (the proof, the present,
    the formula, left side, the assertion), and on "result of".
Everything else predicts 0.
"""
import re

READS = ()

HEADING = re.compile(r"#{2,}$")
SELF_CHECK = {"try", "see", "check", "verify", "confirm", "test", "find", "compute"}
CROSS_REF = {"links", "article", "figure", "below", "reading"}
MATH_NOUN = {"present", "formula", "invention", "assertion", "proof", "statement", "expression",
             "condition", "inequality", "equality", "relation", "proposition", "side", "dot",
             "finally", "finishing", "remainder"}
LATEX = {"align", "style", "ref", "label", "latex", "\\["}
FRAMING = {"general", "art", "terms"}

# typical activation for each group (fitted on sampled training text)
WEIGHTS = {"heading_line": 0.6, "heading_inline": 1.2, "lets": 1.0, "self_check": 0.5,
           "framing": 0.6, "crossref": 2.3, "latex": 2.5, "math_claim": -0.6}


def group(prev, tok, prev_raw):
    if HEADING.match(tok):
        return "heading_line" if prev_raw.endswith("\n") else "heading_inline"
    if tok in ("'s", "’s") and prev in ("let", "let's"):
        return "lets"
    if tok in SELF_CHECK and prev in ("me", "us", "to", "we", "'s", "’s"):
        return "self_check"
    if tok in FRAMING and prev in ("in", "of", "prior", "the", "like"):
        return "framing"
    if tok in CROSS_REF and prev in ("external", "see", "related", "further", "(see"):
        return "crossref"
    if tok in LATEX and prev in ("display", "{", "ref", "label"):
        return "latex"
    if tok in MATH_NOUN and prev in ("the", "left", "right", "both", "of"):
        return "math_claim"
    if tok == "of" and prev == "terms":
        return "framing"
    if tok == "of" and prev == "result":
        return "math_claim"
    return None


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1].strip().lower()
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev_raw = prefix.token_strings[-2] if same_doc else ""
    prev = prev_raw.strip().lower()
    return carry, float(WEIGHTS.get(group(prev, tok, prev_raw), 0.0))

programs.sol:
"""A local approximation to a sparse code-syntax response.

Positive strengths mark control/parameter parentheses, declarations, and
self/this references. Separate whitespace rules distinguish a single blank
after a newline or quote from one after a multi-character indentation token.
Code headers and markers get negative first-token biases; other unmatched
cases are near zero. These are calibrated token patterns, not a parser.
Only four preceding tokens are retained, resetting between documents.
"""
import re

READS = ()
PARENS = {
    'if': 1.933,
    'for': 3.146,
    'foreach': 3.033,
    'while': 1.952,
    'switch': 2.970,
    'catch': 2.657,
    'using': 3.300,
    'function': 0.853,
}
CONTROL_END = re.compile(r'\b(' + '|'.join(PARENS) + r')[`\s]*$')
# Built-in type words, including the first token of size_t.
TYPES = {'int', 'float', 'double', 'long', 'short', 'char', 'byte',
         'bool', 'boolean', 'String', 'string', 'size', 'auto', 'decimal'}
BINDINGS = {'var', 'let', 'const', 'final'}


def response(token, history, first):
    prev = history[-1] if history else ''
    before = history[-2] if len(history) > 1 else ''
    word, prior = token.strip(), prev.strip().strip('`')
    indent = bool(prev) and not prev.strip(' \t')
    newline = prev.endswith('\n')
    escaped = (prev.endswith('\\n') or
               (prev == 'n' and before.endswith('\\')))
    escaped_tab = (prev.endswith('\\t') or
                   (prev == 't' and before.endswith('\\')))
    if first:
        if word in {'def', 'class', 'package', 'import', '#pragma'}:
            return -1.113
        return -0.229 if token.startswith('<|') else 0.0

    # These cases distinguish token boundaries inside whitespace.
    if token == ' ':
        if indent and len(prev) > 1:
            return -0.476
        if escaped:
            return 1.534
        if newline:
            return 0.888
        if prev.endswith(("('", '("')) or prev in {"'", '"', '\"', "\\'"}:
            return 0.653
        return 0.001
    if token.isspace():
        return 0.136 if '\n' not in token and len(token) == 5 else 0.001

    # Parentheses after a control word, allowing Markdown backticks.
    match = CONTROL_END.search(''.join(history))
    control = prior if prior in PARENS else (match[1] if match else '')
    boundary = (not before or before.isspace() or
                before.endswith(('\n', '\\n', '\\t', ';', '{', '}')) or
                before.strip() in {'else', '//', '/*', '*', '+'})
    if control in {'for', 'if', 'while'} and not boundary and '\t' not in prev:
        control = ''
    opening = word.lstrip('`')
    if control and opening.startswith('('):
        rest = opening[1:].lstrip('!$`')
        if rest.startswith('('):
            return 0.610
        if rest and rest not in TYPES | BINDINGS and rest != ')':
            return 0.764
        if rest in TYPES and control in {'for', 'foreach'}:
            return 3.342
        return PARENS[control]

    if word in TYPES | BINDINGS:
        binding = word in BINDINGS
        if word == 'let' and prior == 'if':
            return 1.278
        if word == 'var' and not token.startswith(' '):
            if prev.endswith((';', '{', '}')):
                return 1.633
            if token.startswith('\t') and not (indent or newline):
                return 0.001
        if word == 'const' and token.startswith('\t'):
            return 1.256
        if word == 'auto' and (indent or newline or token.startswith('\t')):
            return 1.926
        if indent or token.startswith('\t'):
            return 1.790 if binding else 0.807
        if newline or escaped or escaped_tab:
            return 1.165 if binding else 0.512
        if prev.strip() == '(' and before.strip() in PARENS:
            if word == 'size':
                return 0.810
            return 3.268 if binding else 1.632
        if prior in {'return', 'new', 'export', 'public', 'private',
                     'static', 'final'}:
            return 0.462 if binding else 0.382
        if prev == '::':
            return 0.210
        if word == 'let':
            return -0.039

    if word == 'self':
        if indent or token.startswith('\t'):
            return 1.201
        if newline or escaped:
            return 0.147
        if (prior in {'if', 'in', 'return', 'yield', '=', '**', 'or', 'and', '('}
                or token == 'self' or any(c in prev for c in '({[=')):
            return 0.679
        return -0.071
    if word == 'this':
        if token.startswith('\t'):
            return 2.301
        if indent:
            return 1.784
        if prior == '$' or prev.endswith('$'):
            return 1.468
        if prior in {'return', '=', 'await'}:
            return 1.543
        if any(c in prev for c in '({[=') or (token == 'this' and not newline):
            return 1.004
    if word.startswith('(self'):
        return 0.511
    if word.startswith('(this'):
        return 1.004
    if word == '$' and token.startswith(' ') and indent:
        return 1.036
    if word == '->' and prior in {'this', '$this'}:
        return 1.884
    if word == '_t' and prior == 'size':
        return 0.719
    return 0.001


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = () if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    value = response(token, history, not history)
    return (doc, (*history[-3:], token)), float(value)

programs.haiku:
"""Layer 1 MLP output unit 271 (layers.1.mlp.down_proj:271).

What it responds to: the start of a statement in source code.

- The opening "(" of an if / for / while / catch / switch condition: strongly positive.
- A code keyword or receiver word (this, self, let, const, var, int, String, $ ...)
  that begins an indented line of code: strongly positive. The same word after
  an operator or bracket mid-line: weakly positive. After a plain English word
  (as in prose): about zero.
- "->" right after "this" (as in this->field): strongly positive.
- A lone space token that starts a line (indentation right after a line break):
  positive. A lone space that continues an indentation run: slightly negative.
- Everything else: about zero.

The program is a small rule table over the newest token, the token before it,
and whether the current token is the first thing on its line. Its state is
just that line-start flag, reset at each document boundary.
"""

READS = ()

CONDITION_WORDS = {"if", "for", "while", "catch", "switch", "elif"}
CODE_WORDS = {"this", "self", "let", "const", "var", "auto", "String", "int",
              "float", "double", "char", "$"}


def step(carry, prefix, upstream):
    new_doc = carry is None or (len(prefix.document_ids) > 1
                                and prefix.document_ids[-1] != prefix.document_ids[-2])
    line_start = True if new_doc else carry
    cur = prefix.token_strings[-1]
    prev_raw = "" if new_doc or len(prefix.token_strings) < 2 else prefix.token_strings[-2]
    prev = prev_raw.strip()
    word = cur.strip().lstrip("(")

    if cur.strip().startswith("(") and prev in CONDITION_WORDS:
        value = 1.9
    elif word in CODE_WORDS:
        if line_start:
            value = 1.3
        elif prev.isalpha():
            value = 0.05
        else:
            value = 0.5
    elif cur.strip() == "->" and prev == "this":
        value = 1.9
    elif cur == " " and "\n" in prev_raw:
        value = 1.0
    elif cur == " " and prev_raw.strip() == "" and prev_raw != "":
        value = -0.4
    else:
        value = 0.0

    # first thing on its line, for the next token
    if "\n" in cur:
        next_line_start = cur.split("\n")[-1].strip() == ""
    else:
        next_line_start = line_start and cur.strip() == ""
    return next_line_start, float(value)

programs.sol:
"""Preview-link completion, code openings, and small grammatical-word biases.

A strong negative pulse is at 'Document' in 'View Full Document'. A
page-count preview has a weaker pulse than an intentionally blurred preview.
At document starts some source-code markers have separate, large responses.
Initial "Hydro" has a positive pulse; wiki-table row separators after a newline
have a negative one. The lowercase preview-link variant is weaker. Control-token
and initial-token-shape rules handle background effects, as do smaller offsets
for English
auxiliaries, negation, and proximal demonstratives. This is an approximation,
not a claim about the model's general syntax.
"""
READS = ()

OBLIGATION = {'must', 'should', 'ought'}
PAST_BE = {'was', 'were'}
PERFECT_HAVE = {'has', 'had'}
PROXIMAL = {'this', 'these'}
CODE_DECLARATIONS = {'package', 'using', 'def', 'class'}


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        position, recent, previous = 0, '', ''
    else:
        _, position, recent, previous = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    text = (recent + token)[-240:]
    value = 0.002

    if token.startswith(' '):
        if word in OBLIGATION:
            value = -0.075
        elif word == 'not':
            value = -0.12 if previous in {'is', 'are'} else -0.025
        elif word == 'been':
            value = 0.08
        elif word in PERFECT_HAVE:
            value = 0.027
        elif word in PAST_BE:
            value = 0.013
        elif word in PROXIMAL:
            value = -0.026
        elif word == 'also':
            value = 0.035

    if token == 'import':
        value = -0.22
    elif token == '</tool_call>':
        value = -0.13

    if position == 0:
        if token in CODE_DECLARATIONS:
            value = -1.4
        elif token.startswith('/*'):
            value = -1.22
        elif token.startswith('#include') or token.startswith('#ifndef'):
            value = -0.8
        elif token in {'import', 'from', '<?'}:
            value = -0.8
        elif token == 'pub':
            value = 2.69
        elif token == 'Hy':
            value = 0.54
        elif token == '<|im_start|>':
            value = -0.27
        elif token == '<|endoftext|>':
            value = -4.07
        elif token.startswith(' ') and word.isascii() and word.isalpha():
            value = -0.17 if word in {'the', 'an'} else 0.14

    if position == 1 and text == 'Hydro':
        value = 2.1
    if token == '|-' and recent.endswith('\n'):
        value = -1.6
    if text.endswith('View Full Document'):
        if 'preview shows document pages' in recent:
            value = -1.1
        elif 'intentionally blurred sections' in recent:
            value = -2.6
        else:
            value = -2.2
    elif text.endswith('View full document'):
        value = -0.8
    return (document, position + 1, text, word), value

"""Heuristic detector for quotation/emphasis openers in running prose.

Negative pulses are strongest after determiners or naming words, and weaker at
sentence/line boundaries or in code-like syntax. Backticks have a smaller pulse;
escaped Unicode quotes and HTML inline-code openers are recognized too. Other
quote marks get a small baseline; ordinary text tokens predict zero.
"""
import re

READS = ()
DETERMINERS = {
    'the', 'a', 'an', 'this', 'that', 'these', 'those', 'some', 'any',
    'each', 'his', 'her', 'their', 'its', 'our', 'your', 'my', 'no',
}
PREPOSITIONS = {
    'of', 'in', 'at', 'as', 'by', 'for', 'to', 'with', 'from', 'on',
    'about', 'into', 'under', 'between', 'than',
}
NAMING_WORDS = {'called', 'named', 'termed', 'entitled', 'meaning'}
CODE_WORDS = {
    'return', 'echo', 'print', 'printf', 'include', 'import', 'case',
    'yield', 'require', 'require_relative', 'puts',
}
CURLY_OPEN = set('“‘„«‹〝')
CORNER_OPEN = {'「', '『', '、「'}
# Unicode escapes, or escaped UTF-8 bytes, for opening curly quotes.
ESCAPED_OPEN = re.compile(
    r'\\+(?:u201[8ace]|xe2\\+x80\\+x9[8ace])$', re.I
)


def predict(token, before):
    s = token.strip()
    left = before.rstrip()
    last = left[-1:]
    word = re.search(r'([\w-]+)$', left)
    word = word[1].lower() if word else ''
    spaced = token[:1].isspace()
    curly = s in CURLY_OPEN or s == ',,' or (s == '”' and spaced)
    corner = s in CORNER_OPEN
    parenthetical = s in ('("', "('", '(“', '(‘')
    emphasis = s in ('*', '**') and spaced
    backtick = s in ('`', '``') and spaced
    ordinary = s in ('"', "'") and spaced
    if not (curly or corner or parenthetical or emphasis or backtick or ordinary):
        if token and token[-1].lower() in '8ace':
            if ESCAPED_OPEN.search(before + token):
                return -1.30
        if token.endswith('>') and (before + token).lower().endswith('<code>'):
            return -0.70
        return -0.05 if s in ('"', "'", '”', '’') else 0.0
    if parenthetical:
        return -0.25 if spaced and last.isalpha() else -0.05
    if not left or not before.rsplit('\n', 1)[-1].strip():
        return -0.03
    if curly or corner:
        if last.isalpha():
            return -0.95 if word in DETERMINERS else (-0.80 if spaced else -0.53)
        return -0.30 if last in ',，、' else -0.15
    if word in CODE_WORDS:
        return 0.04 if ordinary else 0.0
    if word in DETERMINERS or word in NAMING_WORDS:
        return -0.22 if backtick else -0.93
    # Function words remain prose cues even around formulas or markup.
    clean = re.sub(r'<\|[^>]+\|>', '', before[-100:])
    syntax = bool(re.search(r'[=;{}\\]', clean))
    if word in PREPOSITIONS:
        value = -0.30 if syntax else -0.72
    elif last.isalpha():
        value = -0.08 if syntax else -0.57
    elif last in ',，、':
        value = -0.10 if syntax else -0.28
    elif last in '.!?。！？:：;；':
        value = -0.05
    else:
        value = -0.06
    if emphasis:
        if last in ':;：；$' or word in PREPOSITIONS:
            value = -0.70
        elif len(word) == 1:
            value = 0.03
    if backtick:
        value *= 0.4
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    value = predict(token, before)
    return (doc, (before + token)[-200:]), float(value)

programs.haiku:
"""Opening quotation marks that begin a quoted term in English prose.

A quotation mark that opens a quotation, after a word, is strongly negative: the
stronger the more it looks like the start of a named term or phrase (after "a",
"the", "called", "of"...). Straight quotes are weaker than curly ones, and a straight
quote with an odd number of earlier quotes on its line is probably closing one, so it is damped.
"""
CURLY = {'“', '‘', '«', '„', '「', '『', '《'}
STRAIGHT = {'"', "'"}
CUES = {"a", "an", "the", "of", "for", "and", "or", "as", "to", "on", "by", "called", "term", "if", "that", "with", "is"}
READS = ()

def step(carry, prefix, upstream):
    s = prefix.token_strings
    tok = s[-1].strip()
    n = 0 if carry is None else carry      # straight double quotes earlier on this line
    out = 0.0
    if len(s) >= 2 and (tok in CURLY or (tok in STRAIGHT and s[-1].startswith(' '))):
        prev = s[-2].strip().lower()
        if prev[-1:].isalpha():
            strong = prev in CUES
            if tok in CURLY:
                out = -0.9 if strong else -0.7
            else:
                out = -0.7 if strong else -0.35
                if n % 2 == 1:
                    out *= 0.5
    if '\n' in s[-1]:
        n = 0
    elif '"' in s[-1]:
        n += 1
    return n, out

programs.sol:
"""A partial negative-name heuristic for this component.

Accumulate alphabetic token fragments into words. For capitalized Latin
words, use WordNet personal-name aliases, word frequency, and whether the
word continues an earlier token. Listed full names, philosopher names,
and Latin -us/-ius endings receive larger negative offsets.

The high-importance examples motivated these name rules. They do not
capture non-Latin names or the large differences between individual names.
"""
from functools import lru_cache
import wordnet
from wordfreq import zipf_frequency

# Common given names help distinguish first-name context from surnames.
GIVEN = set(
    'John James Robert Michael William David Richard Joseph Thomas Charles '
    'Christopher Daniel Matthew Anthony Mark Paul Peter George Andrew '
    'Edward Henry Alexander Mary Elizabeth Anne Anna Sarah Maria '
    'Roger Martin Stephen Steven Carl Karl Arthur Oscar Walter Albert Alfred '
    'Bob Bill Jean Hans Max Norman Christian Victor Tony'.lower().split()
)
TITLES = {'sir', 'lord', 'saint', 'st', 'pope', 'baron', 'count', 'queen', 'king'}

@lru_cache(None)
def name_sets():
    # Use WordNet's fixed lemma/sense table to find personal-name aliases.
    dictionary = wordnet._wordnet()
    names, full_names = set(), set()
    for (pos, phrase), senses in dictionary.lemmas.items():
        if pos != 'n' or ' ' not in phrase:
            continue
        first = phrase.split(' ', 1)[0].split('-')[0]
        categories = wordnet.categories(first)
        given = (first in GIVEN or first in TITLES or
                 categories == {'noun.person'} or
                 (not categories and zipf_frequency(first, 'en') < 4.5))
        if not given:
            continue
        last = phrase.rsplit(' ', 1)[-1]
        if len(last) < 3 or not last.isalpha():
            continue
        if any(dictionary.synsets[s].category == 'noun.person' for s in senses):
            names.add(last)
            full_names.add(phrase)
    return names, full_names


READS = ()

@lru_cache(maxsize=50000)
def word_properties(word):
    frequency = zipf_frequency(word.lower(), 'en')
    philosopher = wordnet.is_a(word, 'philosopher')
    return frequency, philosopher


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        carry = (document, '', '')
    _, word, previous = carry
    text = prefix.token_strings[-1]
    continued = bool(word and text and text[0].isalpha())
    for ch in text:
        if ch.isalpha():
            word += ch
        else:
            if word:
                previous = word
            word = ''
    state = (document, word, previous)
    value = -0.00032
    if not word or not word[0].isupper() or not text[-1:].isalpha():
        return state, value
    if not all(c.isascii() or 'À' <= c <= 'ÿ' for c in word):
        return state, value
    names, full_names = name_sets()
    w = word.lower()
    frequency, philosopher = word_properties(word)
    known = w in names
    # Each contribution is a small, fitted estimate for a recognizable property.
    if frequency < 3.5:
        value -= 0.03
    if continued and w.endswith('ius'):
        value -= 1.42
    if known:
        value += 0.01
    if known and frequency < 4.5:
        value -= 0.16
    if known and continued:
        value -= 0.13
    if known and w in GIVEN:
        value += 0.03
    if (previous and previous[0].isupper()
            and (previous + ' ' + word).lower() in full_names):
        value -= 0.76
    if previous.lower() in GIVEN:
        value -= 0.05
    if known and philosopher:
        value -= 0.33
    if continued and w.endswith('us'):
        value -= 0.29
    return state, float(value)

"""A token-sensitive detector of the separ- spelling family.

Separation nouns and inflected verbs are strong; adjectival 'separate' is
weaker, and 'separately' is weak. Joining unfinished words handles split
stems and endings. 'Of' just after 'separation' retains a strong response.
Sep abbreviations also respond. Dotted leaders and hiragana ra are negative.
Responses outside these cases are left at zero.
"""
import re
import unicodedata

READS = ()
WORDS = re.compile(r'[^\W\d_]+')
STEM = re.compile(r'[sS]ep[ae]r')
ACTION_CUES = {'to', 'can', 'could', 'will', 'would', 'must', 'should',
               'may', 'we', 'they', 'you', 'not'}
# English inflections, plus common Romance-language separation endings.
ENDINGS = {'', 'ate', 'ated', 'ates', 'ating', 'ation', 'ations', 'ator',
           'ators', 'ately', 'able', 'ability', 'ado', 'ados', 'ada',
           'adas', 'o', 'azione', 'acion', 'acao', 'ateness', 'aten'}


def response(word, fragment, previous, token):
    lower = word.lower()
    stem = STEM.search(word)
    if word.isupper():
        stem = STEM.search(lower)
    if stem:
        ending = lower[stem.start() + 5:]
        if ending not in ENDINGS:
            return 0.0
        if not STEM.search(fragment):
            # Completing the stem is stronger than extending an old stem.
            new_stem = len(word) - len(fragment) < stem.end()
            if ending in {'ately', 'ateness'}:
                return 0.35
            if ending in {'able', 'ability', 'aten'} and not new_stem:
                return 2.5
            if ending in {'ation', 'ations', 'azione', 'acion'}:
                return 10.0 if new_stem else 9.5
            if ending == 'ate' and new_stem:
                return 6.5
            return 9.0 if new_stem else 8.0
        if not ending:
            if word[stem.start()].isupper():
                return 8.0 if stem.start() else 3.9
            return 2.5 if lower.endswith('seper') else 5.4
        if ending == 'ate':
            if word[stem.start()].isupper():
                return 5.0
            if previous in ACTION_CUES or previous.endswith('ly'):
                return 5.6
            return 0.5 if previous in {'a', 'an', 'the', 'some'} else 2.5
        if ending == 'ately':
            return 0.35
        if ending in {'ation', 'ations'}:
            return 7.2
        if ending in {'ator', 'ators'}:
            return 5.3
        if ending == 'ated':
            return 5.2 if '-' in token else 7.0
        if ending in {'ates', 'ating'}:
            return 7.5
        return 6.0
    if lower == 'sep':
        return 1.6 if word[0].isupper() else (5.1 if token == 'sep' else 2.5)
    if lower == 'of' and previous.endswith('separation'):
        return 7.6
    return 0.0


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '')
    _, tail, previous = carry
    text = unicodedata.normalize('NFD', tail + token)
    text = ''.join(c for c in text if unicodedata.category(c) != 'Mn')
    matches = list(WORDS.finditer(text))
    value = 0.0
    for match in matches:
        word = match.group()
        if match.end() > len(tail):
            fragment = text[max(len(tail), match.start()):match.end()]
            value = response(word, fragment, previous, token)
        before_last, previous = previous, word.lower()
    if matches and matches[-1].end() == len(text):
        tail, previous = matches[-1].group()[-48:], before_last
    else:
        tail = ''
    if token and set(token) == {'·'} and len(token) >= 2:
        value = -1.1
    if token == 'ら':
        value = -2.7
    return (doc, tail, previous), value

"""Detect reassembled words, especially split traditional-Chinese compounds.

Recognized words spanning a token boundary get a negative estimate. Traditional
spellings are compared in simplified Chinese, so variant spellings can match
the same dictionary word. Rare fragments completing an all-caps English word
or word-prefix also give a negative signal, as do words repaired across a
hyphenated line break. Document beginnings get a positive offset.
"""
import math
import regex
from functools import lru_cache
from opencc import OpenCC
from wordfreq import get_frequency_dict
import cedict

READS = ()
_SIMPLIFY = OpenCC('t2s')
_ZH = get_frequency_dict('zh')
_EN = get_frequency_dict('en')
_COMMON_PREFIXES = {
    word[:n]
    for word, frequency in _EN.items()
    if frequency >= 10 ** -5.5 and word.isascii() and word.isalpha()
    for n in range(4, len(word))
}

@lru_cache(maxsize=20000)
def compound(previous, token):
    current = token.strip()
    if not regex.fullmatch(r'\p{Script=Han}+', current):
        return 0.0
    match = regex.search(r'\p{Script=Han}+$', previous.strip())
    if not match:
        return 0.0
    previous = match.group()
    best = 0.0
    traditional = False
    dictionary_word = False
    for n in range(1, min(3, len(previous)) + 1):
        word = previous[-n:] + current
        simple = _SIMPLIFY.convert(word)
        f = max(0.0, 9 + math.log10(_ZH.get(simple, 1e-9)))
        if f > best:
            best = f
            traditional = simple != word
            dictionary_word = bool(cedict.glosses(word))
    if len(current) == 1:
        if best > 4.5:
            return -0.60 if traditional else -0.13
        if best > 3.5 and traditional:
            return -0.39 if dictionary_word else -0.10
    return 0.0

@lru_cache(maxsize=20000)
def english_completion(previous, current):
    """Recognize line-break repairs and unusual all-caps word splitting."""
    def frequency(word):
        return max(0.0, 9 + math.log10(_EN.get(word.lower(), 1e-9)))
    split = regex.search(r'([A-Za-z]+)[-\u00ad]\s*\n\s*$', previous)
    word = current.strip()
    if split and word.isascii() and word.isalpha():
        if frequency(split.group(1) + word) > 3.5:
            return -0.70
    if not current.isascii() or not current.isalpha() or not current.isupper():
        return 0.0
    match = regex.search(r'[A-Z]+$', previous)
    if not match:
        return 0.0
    left = match.group()
    a, b = frequency(left), frequency(current)
    whole = frequency(left + current)
    if whole > 3.5:
        if max(a, b) < 2.5:
            return -0.65
        return -0.15 if min(a, b) < 3.5 else 0.0
    if a < 3.5 and b < 2.5 and (left + current).lower() in _COMMON_PREFIXES:
        return -0.30
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    old = b'' if first else carry[1]
    new = prefix.token_bytes[-1]
    before = old.decode('utf-8', 'ignore')
    after = (old + new).decode('utf-8', 'ignore')
    added = after[len(before):]
    value = compound(before[-20:], added)
    if not value:
        value = english_completion(before[-80:], added)
    if first:
        text = new.decode('utf-8', 'replace')
        if text[:1].isspace() and text.isascii():
            value = 0.06
        elif text.isalpha():
            value = 0.29 if text.istitle() else 0.22
        else:
            value = 0.16
    return (doc, (old + new)[-100:]), value

"""A surface detector for particular number endings and code boundaries.

Digit 1 is strongest after 1, 2 or 3, and digit 0 after 3. The response is
weaker inside a longer number; another 1 two digits earlier suppresses it.
Eleven written as a word or a month name also responds. Smaller rules cover
JSON key openings, null comparisons, static imports and doubled backslashes.
At a document boundary there is a broad negative offset instead.
"""
import calendar
import re
import unicodedata

READS = ()
MONTHS = set(calendar.month_name[1:]) | set(calendar.month_abbr[1:])


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        previous, before, digits, tail = '', '', 0, ''
    else:
        _, previous, before, digits, tail = carry
    token = prefix.token_strings[-1]
    if len(token) == 1 and token.isdigit():
        token = unicodedata.normalize('NFKC', token)
    word = token.strip()
    numeric = token.isascii() and token.isdigit()
    value = 0.0

    if first:
        if token.startswith('<|'):
            value = 0.0
        elif token.isdecimal():
            value = -0.06
        elif token.isascii() and word.isalpha():
            value = -0.37
        else:
            value = -0.14
    elif numeric and len(token) == 1 and digits:
        value = -0.025
        if token == '1':
            if previous in ('1', '2', '3'):
                base = 1.06 if previous == '1' else 0.98
                if previous == '3':
                    base = 0.78
                if digits == 1:
                    value = base
                elif before == '1':
                    value = -0.05
                    if digits > 2 and previous == '1':
                        value = -0.30
                else:
                    value = base * (0.46 if digits == 2 else 0.57)
                    if previous == '3':
                        value = 0.31
            elif previous == '0':
                value = -0.21 if digits == 1 else -0.05
            else:
                value = 0.23 if digits == 1 else 0.08
        elif token == '0':
            if previous == '3':
                value = 0.66 if digits == 1 else 0.23
            elif previous == '0':
                value = 0.12 if digits == 1 else -0.03
            elif previous == '1' and digits > 1:
                value = -0.10
            elif previous == '4':
                value = -0.13
            elif previous in '56789':
                value = -0.07
        elif token == '2' and previous in '12':
            value = 0.10
        elif previous == '3':
            value = -0.065
    elif re.search(r'\beleven(?:th)?\Z', tail.lower() + token.lower()):
        value = 2.0 if (tail + token).lower().endswith('th') else 1.10
    elif word.lower() in ('one', 'first') and re.search(
        r'\b(?:twenty|thirty)[ -]$', tail.lower()
    ):
        value = 1.20
    elif word in MONTHS:
        value = 0.72 if word == 'November' else -0.10
        if word == 'Nov':
            value = 0.48
    elif word in ('nil', 'null') and tail.rstrip().endswith(('!=', '==')):
        value = 0.73 if word == 'nil' else 0.63
    elif word == 'None' and tail.rstrip().endswith((' is', ' is not')):
        value = 0.35
    elif word == 'static':
        value = -2.45 if previous.strip() == 'import' else -0.12
    elif token == '{"':
        value = 0.30 if tail.rstrip(' \t').endswith('\n') else 0.08
    elif token == ' "' and '\n' in tail:
        if not tail.rsplit('\n', 1)[-1].strip():
            value = 0.28
    elif word == '\\\\':
        # A TeX row break differs from escaping a backslash in source code.
        tex = ('\\hat', '\\frac', '\\right', '\\hfill', '\\otimes')
        value = 0.65 if any(command in tail for command in tex) else -0.32

    new_digits = digits + len(token) if numeric else 0
    return (doc, token, previous, new_digits, (tail + token)[-80:]), value

programs.haiku:
"""Fires on the units digit of a two-digit number whose tens digit is 1, 2 or 3,
mainly the digit 1 (11, 21, 31, e.g. 'December 31'), plus '30'. Also a constant
negative value on the first token of each document."""

READS = ()

ONE_AFTER = {"1": 1.0, "2": 0.9, "3": 0.8, "4": 0.3}
DIGITS = set("0123456789")
START = -0.3


def step(carry, prefix, upstream):
    s = prefix.token_strings
    docs = prefix.document_ids
    t = prefix.position
    if t == 0 or docs[-1] != docs[-2]:
        return carry, START
    cur, prev = s[-1], s[-2]
    if cur not in DIGITS or prev not in DIGITS:
        return carry, 0.0
    if t >= 2 and docs[-3] == docs[-2] and s[-3] in DIGITS:
        return carry, 0.0
    if cur == "1":
        return carry, ONE_AFTER.get(prev, 0.1)
    if cur == "0" and prev == "3":
        return carry, 0.65
    return carry, 0.0

programs.sol:
"""A signed detector for short grammatical phrases.

Positive examples include 'as compared', 'that of', and embedded wh-clauses;
negative examples include 'if necessary', 'in any', and 'at the same'.
The dictionaries spell out phrase endings, grouped by their grammatical
introducer.  Most content words get zero.  Labels and abbreviations have
separate punctuation rules.  State holds two preceding tokens and the latest one's
capitalization, resets at document boundaries, and gives a small negative
baseline at a document's first token.  The signed levels summarize training
examples; this is a partial approximation, not a general syntactic parser.
"""
READS = ()

# Comparison, qualification, and prepositional discourse expressions.
AFTER = {
    'as': {
        'compared': 3.65, 'per': 2.4, 'such': 1.55, 'if': -1.4,
        'though': -1.7, 'follows': .52, 'before': -.58,
        'opposed': .8, 'against': 2.4, 'part': .47, 'of': .59,
        'is': .78, 'that': .67, 'shown': -.38,
        'appropriate': -1.3, 'applied': 1., 'being': .47,
    },
    'in': {
        'turn': 1.58, 'between': 1.1, 'recent': -1.25,
        'writing': -.73, 'some': -.41, 'other': -.3, 'today': -1.1,
    },
    'at': {'times': 1.55, 'once': .7, 'regular': -1.2, 'par': 1.7},
    'with': {'regards': 2.4, 'respect': .33},
    'when': {'compared': 2.32},
    'by': {'contrast': 1.35},
    'or': {'otherwise': 1.18},
    'and': {'then': -.34},
    'if': {'necessary': -1.16, 'and': -.9, '__': -1.65},
    'that': {'of': 1.64, 'which': 1.24, 'much': 1.3, 'too': 1.8},
    'from': {'one': .64, 'within': 1.16},
    'some': {'of': -.22},
}
PREPOSITIONS = {'of', 'to', 'for', 'with', 'from', 'by', 'in', 'at'}
WH = {'what': .95, 'how': 1.5, 'why': 1.6, 'where': .5}
COPULAS = {'is', 'was', "'s", '’s', "that's", 'that’s'}
DETERMINERS = {'the', 'a', 'an', 'each', 'every', 'your', 'our', 'their'}


def response(word, previous, earlier, capital=False):
    if word in WH:
        if previous in COPULAS:
            return WH[word]
        if previous == 'that':
            return {'what': 1.14, 'how': 2., 'why': .5, 'where': .2}[word]
        if previous in PREPOSITIONS:
            return {'what': .45, 'how': .8, 'why': .6, 'where': .45}[word]
        if previous in {'and', 'or', 'but'}:
            return .55 if word in {'how', 'why'} else .08
        if previous in {'as', 'than', 'like'}:
            return 1.8 if word in {'what', 'how'} else 0.
        if previous == 'not' and word == 'what':
            return .65
        return 0.
    if word == 'any':
        return {'at': -2., 'in': -.92, 'to': -.39, 'for': -.42,
                'by': -.84, 'of': -.25, 'with': -.3,
                'from': -.4, 'into': -.4}.get(previous, 0.) * (1.6 if capital else 1.)
    if previous == 'the':
        if word == 'same':
            return -1.75 if earlier == 'at' else -.15
        if word in {'time', 'moment'}:
            return 1.4 if earlier in {'at', 'by'} else .12
        if word == 'world':
            return -.95 if earlier == 'in' else -.08
        if word in {'right', 'left'}:
            return -.85 if earlier in {'on', 'to'} else -.08
        if word == 'form':
            return -.76 if earlier == 'in' else 0.
        if word == 'way':
            return 1.85 if earlier == 'by' else .15
        if word == 'other' and earlier == 'on':
            return -.65
        if word in {'one', 'ones'}:
            return .77 if word == 'one' else 1.25
        if word == 'invention':
            return -.55
        if word in {'purpose', 'purposes'}:
            return .85 if earlier == 'for' else .15
    if previous == 'a' and earlier == 'as':
        return {'result': 1.25, 'consequence': 1.1, 'part': .7}.get(word, 0.)
    if previous == 'per':
        return 2.7 if word in DETERMINERS else (2.1 if word == 'se' else 0.)
    if word in {':', '：', ':\n', ':\n\n'}:
        return {'re': 2.8, 'that': .18, 'which': .3, 'include': .26,
                'including': 1.05, 'of': .96,
                'with': .55, 'by': .85, 'to': .6, 'from': .67,
                'at': .52, 'in': .55, 'is': .23, 'are': .27,
                'no': .9}.get(previous, 0.)
    if word == ',' and previous in {'and', 'if'}:
        return -.4 if previous == 'and' else -1.4
    if word == '.' and previous in {'.e', '.g'}:
        return .3 if previous == '.e' else .2
    if (word == '.' and not capital and len(previous) == 1
            and previous.isascii() and previous.islower()):
        return -.8 if previous == 'i' else -.35
    if len(word) >= 2 and set(word) == {'·'}:
        return -1.24
    value = AFTER.get(previous, {}).get(word, 0.)
    if capital and previous in {'as', 'in', 'at'}:
        value *= 1.5
    return value


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        previous, earlier, capital = '', '', False
        fresh = True
    else:
        _, previous, earlier, capital = carry
        fresh = False
    raw = prefix.token_strings[-1].strip()
    word = raw.lower()
    value = response(word, previous, earlier, capital)
    if fresh and value == 0.:
        value = -.1
    return (document, word, previous, raw[:1].isupper()), float(value)

"""A partial recognizer of source metadata rather than ordinary prose.

Publication/resource fields, access phrases and scholarly links score negatively;
scientific headings score positively. Separate small rules cover document openings
and typography. Constants were fitted on training activations. This deliberately
leaves most token-specific variation unexplained.
"""
import re

READS = ()
LABELS = set(
    "title titles author authors contributor contributors publisher publishing "
    "publication publications journal volume issue date isbn issn doi url "
    "citation citations bibliography abstract keywords affiliation affiliations "
    "advisor advisors degree department audience format pages page".split()
)
DISTRIBUTION = set(
    "copyright licence license licensed permission permissions unrestricted "
    "attribution repository access available availability download downloadable "
    "pdf epub full text item identifier handle".split()
)
ACCESS = set(
    "access available availability download downloadable pdf epub full text "
    "item identifier handle".split()
)
SECTIONS = set(
    "background introduction methods methodology results discussion conclusion "
    "conclusions acknowledgments acknowledgements definitions contributions "
    "availability".split()
)
QUESTIONS = set("what how why where when who which".split())
DETERMINERS = set("the a an this that these those".split())
PRONOUNS = set("i we you he she it they my our your his her their".split())
META = re.compile(
    r"\b(?:doi|isbn|issn|citation|publisher|authors|repository|bibliography)\b",
    re.I,
)
SCHOLARLY = re.compile(
    r"(?:\bdoi\b|arxiv|pubmed|ncbi|\.edu|\.ac\.|\([12][0-9]{3}\))", re.I
)
ADDRESS = re.compile(r"https?://[^\s<>`]*$", re.I)
LICENSE_CONTEXT = re.compile(
    r"creative commons|this article|open.access|unrestricted", re.I
