    match = re.search(r"([A-Za-z]+)$", old[-40:] + token)
    word = match.group(1).lower() if match else low
    partial = None
    if token[:1].isascii() and token[:1].isalpha():
        partial = re.search(r"[A-Za-z]+$", old)
    before_word = old[:partial.start()] if partial else old
    line = before_word.rsplit("\n", 1)[-1]
    heading = not line.strip(" \t-*#|>") or (
        len(line) < 35 and line.lstrip().startswith(("#", "-"))
    )
    metadata = bool(META.search(old[-180:]))
    scholarly = bool(SCHOLARLY.search(old[-180:]))
    address = bool(ADDRESS.search(old[-250:]))
    protocol = low in ("http", "https") or s == "://"
    upper = len(s) > 1 and s.isascii() and s.isalpha() and s.isupper()
    value = -0.003

    # Formatting and source addresses.
    if s == "|":
        value -= 0.052
    if token in ("\\n", "\\t"):
        value -= 0.042
    if len(s) >= 2 and set(s) == {"·"}:
        value += 0.668
    if low in ("fig", "figs") and upper:
        value -= 0.150
    if protocol:
        value -= 0.075
    if protocol and scholarly:
        value -= 0.253
    if address and scholarly:
        value -= 0.091

    # Field names and publication availability, not every occurrence of a noun.
    if word in LABELS and heading:
        value -= 0.117
    if word in LABELS and metadata:
        value -= 0.290
    if word == "audience" and (heading or metadata):
        value -= 1.440
    if word in ("isbn", "issn", "doi", "pmid", "pmc", "zbl"):
        value -= 0.239
    if word == "access" and re.search(r"\bopen[- ]?$", old, re.I):
        value -= 0.224
    if word == "text" and re.search(r"\bfull\s*$", old, re.I):
        value -= 0.732
    if word in DISTRIBUTION and LICENSE_CONTEXT.search(old[-200:]):
        value -= 0.432
    if word in ACCESS and metadata:
        value -= 0.664
    if metadata and s and not any(c.isalnum() for c in s):
        value -= 0.051
    if word == "item" and re.search(r"identifier|cite or link", old[-150:], re.I):
        value -= 2.412
    if word == "handle" and address:
        value -= 1.940

    # Headings and the start of scientific exposition contrast with metadata.
    if word in SECTIONS and heading:
        value += 0.112
    if word in SECTIONS and upper:
        value += 0.336
    if low == "we" and re.search(
        r"in this (?:paper|article|study),?\s*$", old[-60:], re.I
    ):
        value += 0.313

    # Opening formats have a different baseline from words inside a document.
    if position == 1 and old == "Title" and s == ":":
        value += 2.105
    if position == 1 and word == "citation":
        value -= 1.604
    if position == 0:
        value += 0.046
        if s.isdigit():
            value -= 0.221
        if s.isascii() and s.isalpha() and s.islower():
            value += 0.060
        if len(s) == 1 and s.isascii() and s.isupper():
            value -= 0.244
        if len(s) == 1 and s.isascii() and s.islower():
            value += 0.124
        if low in QUESTIONS:
            value -= 0.450
        if low in DETERMINERS:
            value -= 0.363
        if low in PRONOUNS:
            value -= 0.179
        if low in ("not", "non"):
            value += 0.736
        if s == ",":
            value += 0.218
        if s.startswith("#"):
            value += 0.163
        if token in ("\\t", "\\n"):
            value -= 1.187
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, old = 0, ""
    else:
        _, position, old = carry
    token = prefix.token_strings[-1]
    value = _score(token, old, position)
    return (doc, position + 1, (old + token)[-400:]), float(value)

