"""layers.1.mlp.down_proj:280 -- a weak, mostly token-level predictor.

This component's activation is small and spread thinly over many tokens, so no
simple rule explains most of it. These parts have a consistent sign:

1. The first token of a document. The model sees no earlier text there, so its
   value depends on the token alone: a word fragment that starts mid-word is
   positive, a capitalised word or a digit is negative.
2. Web and markup syntax (URLs, "FIG", "](", ",None", table bars " |") is negative.
3. Labels from bibliographic and catalogue records (Publisher, ISBN, Keywords,
   Advisor, Title, ...) are negative, and section headings of research
   abstracts (RESULTS, Background, Discussion, Introduction) are positive.

Everything else predicts 0.
"""

import re

READS = ()

WEB_SYNTAX = re.compile(r"://|http|\.pdf|\.com$|\.org$|\]\(|FIG|CONFIG$")
TABLE_BARS = {" |", "|\n", "|"}
WEB_WORDS = {",None"}
RECORD_LABELS = {
    "package", "eng", "Abstract", "Title", "Pages", "Issue", "ISBN", "Publisher",
    "Keywords", "Advisor", "Advisors", "Publication", "Citation", "Scholar",
}
HEADINGS = {"RESULTS", "Results", "BACKGROUND", "Background", "Discussion",
            "DISCUSSION", "Introduction", "INTRODUCTION"}

WEB_VALUE = -0.10
BAR_VALUE = -0.08
RECORD_VALUE = -0.12
HEADING_VALUE = 0.20


def start_value(text):
    """Activation at a document's first token, by what the token looks like."""
    if not text.strip():
        return -0.08
    if text[0] == " ":
        return 0.05
    if text[0].isdigit():
        return -0.17
    if text[0].isalpha():
        return 0.21 if text[0].islower() else -0.07
    return 0.08


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    word = text.strip()
    at_start = len(prefix.document_ids) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if at_start:
        return None, start_value(text)
    if word in HEADINGS:
        return None, HEADING_VALUE
    if word in RECORD_LABELS or text in WEB_WORDS:
        return None, RECORD_VALUE
    if text in TABLE_BARS:
        return None, BAR_VALUE
    if WEB_SYNTAX.search(text):
        return None, WEB_VALUE
    return None, 0.0

"""Words that point toward a place or goal: "beyond", "above", "past", "reach", "enter",
"pass", and "to" when it follows a word of returning or moving ("back to", "return to",
"closer to", "handed it to"). Infinitive "to" is not counted."""

READS = ()

TARGET_WORDS = {
    "beyond": 1.0, "above": 0.7, "past": 0.7, "below": 0.6, "inside": 0.5,
    "reach": 0.6, "reaches": 0.6, "reached": 0.5, "pass": 0.5, "passes": 0.5,
    "enter": 0.5, "enters": 0.5, "entered": 0.5, "encounters": 0.4,
    "进入": 1.0, "前往": 0.4, "向": 0.6, "於": 0.6,
}

MOTION_CUES = {
    "back", "return", "returned", "returns", "closer", "close", "handed", "brought",
    "sent", "moved", "moving", "move", "went", "come", "came", "get", "got",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    value = TARGET_WORDS.get(word, 0.0)
    if word == "to" and len(prefix.token_strings) > 1:
        if prefix.token_strings[-2].strip().lower() in MOTION_CUES:
            value = 0.6
    return carry, float(value)

"""Component layers.1.mlp.down_proj:285, a document-start detector.

What it does, in plain terms:
- It fires strongly on the second or third token of a document when the
  document opens with a number and the next token is a symbol or punctuation
  mark, e.g. "6:", "8 -", "5 =", "2,", "8 /" at the very start of a text.
  The strongest firing is on the token straight after the opening number
  (position 1), somewhat weaker one token later (position 2).
- Other tokens right after a word-initial punctuation mark get a weak positive value.
- The first token of a document is mildly negative, so the component is
  slightly below zero there.
- Everywhere else it is silent (0).

The position counter restarts at each document id change, as the model does.
"""

READS = ()

FIRST_TOKEN = -0.3      # first token of a document (mildly negative)
NUMBER_THEN_SYMBOL = {1: 5.0, 2: 3.0}   # by position, symbol after an opening number
NUMBER_THEN_WORD = {1: 3.1, 2: 2.4}     # by position, word after an opening number
PUNCT_AFTER_WORD = 0.4                  # punctuation right after a word, position 1


def _is_number(s):
    return s.strip().isdigit()


def _is_symbol(s):
    s = s.strip()
    return s != "" and not any(c.isalnum() for c in s)


def _is_word(s):
    return any(c.isalpha() for c in s)


def step(carry, prefix, upstream):
    # carry: (document id, position in document, previous token string) or None
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        pos, prev = 0, None
    else:
        pos, prev = carry[1] + 1, carry[2]
    carry = (doc, pos, token)

    if pos == 0:
        return carry, FIRST_TOKEN
    if prev is not None and _is_number(prev) and pos in NUMBER_THEN_SYMBOL:
        if _is_symbol(token):
            return carry, NUMBER_THEN_SYMBOL[pos]
        if _is_word(token):
            return carry, NUMBER_THEN_WORD[pos]
    if pos == 1 and _is_symbol(token) and prev is not None and _is_word(prev):
        return carry, PUNCT_AFTER_WORD
    return carry, 0.0

