"""Detect the spelling fragment 'lat', especially a token split as l|at.

The complete word 'late' is also strong (less so after a degree word like
"too"). Long, familiar derivatives usually give smaller responses. A small
within-word echo covers continuation tokens. Accents and Cyrillic spellings
are normalized; state is cleared at each new document.
"""
import re
import unicodedata
import regex
from anyascii import anyascii

READS = ()


def normalize(text):
    if regex.search(r'\p{Script=Cyrillic}', text):
        text = anyascii(text)
    return ''.join(c for c in unicodedata.normalize('NFKD', text.lower())
                   if not unicodedata.combining(c) and c != '\x00')


def fragment(s, tail):
    word = s.strip()
    if tail.endswith('l') and s.startswith('at'):
        # Common derivations suppress the otherwise strong split syllable.
        if tail.endswith(('templ', 'legisl')):
            return -0.25
        if tail.endswith('rel') and len(word) >= 3:
            return -2.5 if word == 'ate' else -0.25
        if word.startswith(('ation', 'ating', 'ated')):
            if tail.endswith(('ul', 'yl')):
                return -0.25
        if word in ('at', 'ats', 'ate', 'ater', 'ator', 'ative'):
            return -6.0 if word == 'at' else -5.3
        if word.startswith('ation'):
            if word.endswith('s'):
                return -0.5
            return -3.5 if tail.endswith('ll') else -2.6
        if word in ('ating', 'ated', 'ates'):
            return -2.4
        return -3.0 if len(word) <= 4 else -0.9
    if tail.endswith('l') and re.match(r'a[cdk]', s):
        return -0.35 if s.startswith('ac') else -0.8
    if tail.endswith('la') and s.startswith('t'):
        return -4.0 if s == 't' else -1.3
    if word == 'late':
        previous = tail.split()[-1] if tail.split() else ''
        if s != word and previous in ('too', 'quite', 'bit'):
            return -1.9
        if s != word and previous in (
                'the', 'in', 'to', 'of', 'his', 'her', 'their', 'our'):
            return -5.8
        return -3.8 if s == word else -4.1
    if word == 'lat':
        return -4.5 if s == word else -3.0
    if word.startswith('lat'):
        if word.startswith('later') and word != 'lateral':
            return -0.2
        if word.startswith('latt'):
            return -0.5 if word.startswith('lattice') else 0.1
        if word.startswith('latin'):
            return -0.7
        if word.startswith('latex'):
            return -1.5 if s == word else -0.5
        if word.startswith('lation'):
            return -3.7 if tail.endswith(('f', 'b')) else -0.8
        return -1.2
    if word.startswith('flat'):
        return -1.1
    if word.startswith('translat'):
        return -1.75
    if word.startswith(('inflat', 'deflat')):
        return -0.8
    if word.startswith(('ilat', 'bilat')):
        return -1.7
    if word.startswith('plat') and len(word) <= 4:
        return -2.8
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail, old = ('', 0.0) if carry is None or carry[0] != doc else carry[1:]
    raw = prefix.token_strings[-1]
    s = normalize(raw)
    value = fragment(s, tail)
    if 'л' in raw.lower() and s.strip() in ('lat', 'plat'):
        value *= 0.6
    if s[:1].isalpha() and tail[-1:].isalpha() and old < -0.5:
        value += 0.2 * old
    return (doc, (tail + s)[-10:], value), value

