"""Activation of the 'make/take' component. It fires on general action verbs used as
verbs in a clause: make and take (and their inflections) most strongly, then do, get,
go, come, give, put, pull, bring, tell, leave and friends, more weakly with let, set,
call, ask, start, run. The strength depends on the words before: right after 'to', a
modal or a pronoun the verb is strongest; after an article, 'of', or in code it is
almost silent (except for make/take). The first token of each document is slightly
negative."""
MAKE_TAKE = {"make", "made", "making", "makes", "take", "took", "taken", "taking", "takes", "pull", "bring", "brought", "tell", "told", "leave", "leaving", "push"}
OTHER = {"go", "went", "goes", "going", "come", "came", "comes", "coming", "turn", "turned", "turns", "pay", "paid", "give", "gave", "given", "gives", "put", "putting", "do", "did", "does", "doing", "done", "get", "gets", "getting", "got", "send", "keep", "kept", "keeps", "carry", "hold", "throw", "buy", "spend", "cut", "hit", "draw"}
WEAK = {"let", "set", "call", "ask", "asked", "start", "started", "run", "try", "find", "pick"}
NOUN_BEFORE = {"the", "a", "an", "of", "this", "that", "his", "her", "my", "your", "its", "our", "their", "how", "what", "where", "which", "int", "void"}
CODE = set("{}()[];<>=.,")
VERB_BEFORE = {"to", "will", "can", "could", "would", "should", "must", "I", "you", "we", "they", "he", "she", "and"}
READS = ()

def step(carry, prefix, upstream):
    toks = prefix.token_strings
    if len(toks) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, -0.22
    word = toks[-1].strip().lower()
    before = toks[-2].strip()
    if word in MAKE_TAKE:
        return None, 0.85 if (before in VERB_BEFORE) else 0.65
    if word in OTHER:
