"""Approximate a bio-/biology vocabulary detector, not a general topic model.

A token gets a strong positive score when it completes bio-, botan- or
organism across a token boundary. Whole words and living-system phrases
receive smaller, fitted scores. Non-biological bi- continuations can be
negative. Several scripts are recognized, including Chinese biology terms.
A secondary cue is repeated middle dots. Unmatched text is nearly zero.
Only a short byte suffix is remembered, resetting at document boundaries.
"""
import re
READS = ()
BIO = re.compile('bio|био|βιο|バイオ|바이오')
BOTANY = re.compile('botan')
ORGANISM = re.compile('organism|organizm|организм')
KARYOTE = re.compile('(?:eu|pro)karyot')

def onset(pattern, before, token):
    """Return True for a split stem, False for a whole one, None if absent.

    Only matches ending in the newest token count.
    """
    boundary = len(before)
    for m in pattern.finditer(before + token):
        if m.end() > boundary:
            return m.start() < boundary
    return None

def activation(before, token):
    before, s = (before.lower(), token.lower())
    joined = before + s
    word = re.search('[^\\W\\d_]+$', before)
    word = word.group() if word else ''
    embedded = bool(word and s and s[0].isalpha())
    clean = s.strip()
    if clean and set(clean) == {'·'} and (len(clean) >= 2):
        return 1.6
    # Biology prefixes: spelling and token boundaries both matter.
    found = onset(BIO, before, s)
    if found is not None:
        if re.search('biograph|biograf|биограф', joined):
            return -0.83 if found else 0.21
        if re.search('biometr|antibiot', joined):
            return -0.02
        if found:
            if re.search('biops', joined):
                return 1.38
            if word not in ('b', 'bi') and clean == 'io':
                return 2.96
            if re.search('biotech|biocom', joined):
                return 7.36 if len(clean) <= 5 else 3.92
            if re.search('biome|bios$', joined):
                return 2.82
            if clean in ('olog', 'ologie', 'ologists', 'ologist'):
                return 5.67
            if any((c in joined for c in ('био', 'βιο', 'バイオ', '바이오'))):
                return 8.29
            if len(word) > 2 and (not word.endswith('b')):
                return 3.13
            if len(clean) <= 3:
                return 6.66
            return 2.49
        if re.search('biol(?:ogy|ogie|ogia|ogía)?$', clean):
            return 5.1 if embedded else 3.48
        if 'biolog' in s:
            return 2.45
        if clean == 'bio':
            return 0.9 if embedded else 2.92
        if re.search('biom|bios|biochem|biomed|biopsy', s):
            return 0.54
        return 1.87
    if re.search('bio[a-z]{0,2}$', before) and s and s[0].isalpha():
        if re.search('biodiversity|biosphere|biomim', joined):
            return 5.54
        if re.search('biochem|bioinform|biocontrol', joined):
            return 2.65
        if re.search('bioavail|biodistribut|biograph|biometr', joined):
            return -0.02
        return 0.85
    # Other biological roots and their immediate suffixes.
    found = onset(BOTANY, before, s)
    if found is not None:
        return (6.38 if len(clean) <= 3 else 3.27) if found else 0.15
    if (re.search('(?:biolog|биолог|ecolog|эколог)$', before)
            and s and s[0].isalpha()):
        return 1.1
    if word.endswith('botan') and s and s[0].isalpha():
        return 2.25
    found = onset(ORGANISM, before, s)
    if found is not None:
        if found and 'организм' in joined:
            return 1.77
        return 5.92 if found else 3.31
    if onset(KARYOTE, before, s) is not None:
        return 5.45
    if onset(re.compile('生物'), before, s) is not None:
        return 3.86
    if onset(re.compile('生き物'), before, s) is not None:
        return 3.51
    if clean in ('生命', '生态', '物种'):
        return 1.0
    if before.endswith('仿') and s.startswith('生'):
        return 4.68
