    if onset(re.compile('ecosystem|экосистем'), before, s) is not None:
        return 1.04
    if onset(re.compile('ecolog|эколог'), before, s) is not None:
        return 0.56
    if onset(re.compile('生化|生物質'), before, s) is not None:
        return 2.42
