        return -0.76
    if word == 'b' and s.startswith('ism'):
        return 1.43
    if word == 'b' and s.startswith('im'):
        return 4.14
    if clean in ('cell', 'cells', 'bacteria'):
        return 0.12
    if clean == 'microbial':
