    if token == ' as' and re.search(r'\(also known$', text):
        return 0.75
    if token == ' words' and re.search(r'\d$', text):
        return 2.27 if re.search(r'\(\d+$', text) else 0.55
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        text, position = '', 0
    else:
        _, text, position = carry
    token = prefix.token_strings[-1]
    value = predict(text, token, position)
    return (doc, (text + token)[-160:], position + 1), value

programs.haiku:
"""Lexical detector for the "b" syllables of Arabic personal-name particles, and for a few
"bus" / "bola" / "bol" words, read off the word being typed.

What the component does, in plain terms:
- Strongly negative on the particles that open Arabic/Islamic personal names:
  "ibn" (about -14, as in "Ibn Battuta", "ibn Abi Talib"), and "Abu", "bint", "Abd-" as in
  Abdullah (about -6 to -9).
- Mildly negative on short name syllables such as "bou", "ben", "bu", "bn".
- Positive on the word "bus" and on words ending in "bus" (omnibus, globus, syncbus),
  about +3 to +3.5, and on "babel", "bola", "bolus", "parabola" (about +3.4), and "bol"
  words such as futebol (about +1.5).
- About zero everywhere else, including ordinary "bus"-free words like "business".

The program keeps the current word (the letters typed since the last space, punctuation or
digit, within the document) and returns the average activation of its class. It has no
other state.
"""

READS = ()

# Name particles, value = the component's average activation on them.
IBN = {"ibn": -14.0, "ابن": -14.0}
NAME_PARTICLES = {
    "abu": -8.5, "أبو": -9.0, "abou": -11.0,
    "bint": -8.1, "بنت": -8.0,
    "abd": -5.7, "abdul": -4.0, "abdel": -4.9, "عبد": -6.0,
    "bnb": -5.2,
}
SHORT_SYLLABLES = {"bou": -3.4, "ben": -1.5, "bu": -1.0, "bn": -1.2}

# "bus" words and "bola"-type words.
BUS_WORDS = {"bus": 1.7, "buses": 1.6}
BOLA_WORDS = {"babel": 4.0, "boli": 3.2, "boll": 3.2, "boles": 2.1, "bolus": 4.2}
BOL_WORDS = {"bol": 1.5, "futebol": 1.5, "ebola": 1.5}
NOT_BUS = {"syllabus", "business", "robust", "combustion"}


def current_word(prefix):
    """The letters typed since the last space, punctuation or digit, in this document."""
    word = ""
    doc = prefix.document_ids
    for j in range(prefix.position, max(-1, prefix.position - 24), -1):
        if doc[j] != doc[-1]:
            break
        s = prefix.token_strings[j]
        letters = ""
        for ch in reversed(s):
            if not ch.isalpha():
                break
            letters = ch + letters
        word = letters + word
        if letters != s:
            break
    return word.lower()


def step(carry, prefix, upstream):
    w = current_word(prefix)
    if w in IBN:
        value = IBN[w]
    elif w in NAME_PARTICLES:
        value = NAME_PARTICLES[w]
    elif w in SHORT_SYLLABLES:
        value = SHORT_SYLLABLES[w]
    elif w in BUS_WORDS:
        value = BUS_WORDS[w]
    elif w in BOLA_WORDS:
        value = BOLA_WORDS[w]
    elif w in BOL_WORDS:
        value = BOL_WORDS[w]
    elif w.endswith("bus") and w not in NOT_BUS:
        value = 3.5
    elif w.endswith("bola"):
        value = 3.4
    else:
        value = 0.0
    return None, float(value)

programs.sol:
"""Short alphanumeric names and acronym fragments produce negative activations.

The strongest response is to the first few digits of a letter-number label.
Lowercase word-like prefixes weaken this response; interleaved letters and
numbers strengthen it. Single-letter acronym continuations also respond.
Fullwidth letters and digits count too, but hexadecimal byte escapes do not.
There is a separate negative baseline at the start of each context.
"""
import re
import unicodedata

READS = ()


def ascii_letters(s):
    return bool(s) and s.isascii() and s.isalpha()


def numeric_suffix(stem, count, mixed):
    size = len(stem)
    if stem.isupper():
        if count >= 2:
            return -0.4 * 0.7 ** (count - 2)
        if count == 1:
            return -1.05 if size == 1 else -0.6 if size == 2 else -0.15
        return -0.8 if size <= 2 else -0.5 if size == 3 else -0.15
    if count:
        return (-0.3 if size <= 2 else 0.08) if count == 1 else -0.05
    if mixed:
        return -0.8 if size <= 2 else -0.5 if size == 3 else -0.25
    if size <= 2:
        return -0.3 if size == 1 else -0.45
    return -0.25 if size == 3 else -0.1


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    if start:
        tail, previous, gap, escape = '', '', 0, 0
    else:
        _, tail, previous, gap, escape = carry
    token = ''.join(
        unicodedata.normalize('NFKC', ch)
        if unicodedata.east_asian_width(ch) == 'F' else ch
        for ch in prefix.token_strings[-1]
    )
    value = 0.003
    suffix = re.search(r'([A-Za-z]+)([0-9]*)$', tail)
    if token.isascii() and token.isdigit() and suffix:
        stem, digits = suffix.groups()
        if gap == 0:
            mixed = any(ch.isdigit() for ch in tail[:suffix.start()])
            value = numeric_suffix(stem, len(digits), mixed)
        elif stem.isupper() and len(stem) <= 2:
            value = -0.3
    elif not token[:1].isspace():
        piece = token.lstrip('-.')
        prev = previous.strip()
        if ascii_letters(piece) and len(piece) <= 2:
            if (ascii_letters(prev) and len(prev) <= 2
                    and (piece == token or prev.isupper())):
                if piece.isupper():
                    if len(piece) == 1:
                        value = -0.3 if prev.isupper() else -0.6
                    else:
                        value = -0.12
                elif len(piece) == 1:
                    value = -0.22 if prev.isupper() else -0.1
            elif prev.isascii() and prev.isdigit():
                if len(piece) == 1:
                    value = -0.48 if suffix and len(suffix[1]) <= 2 else -0.15
                elif piece.isupper():
                    value = -0.2
    if escape:
        value = 0.003
    if start:
        if token.isascii() and token.isalnum():
            value = -0.4
        else:
            value = -0.25 if len(token.strip()) > 2 else -0.05
    # Retain just the trailing identifier, bridging one whitespace token.
    match = re.search(r'[A-Za-z0-9]+$', token)
    if match:
        piece = match[0]
        tail = (tail + piece)[-64:] if match.start() == 0 and gap == 0 else piece
        gap = 0
    elif token.isspace() and gap == 0:
        gap = 1
    else:
        tail, gap = '', 0
    # Two hexadecimal characters after a literal byte-escape introducer.
    if token.endswith('\\x') or (previous.endswith('\\') and token == 'x'):
        escape = 2
    elif escape and all(ch in '0123456789abcdefABCDEF' for ch in token):
        escape = max(0, escape - len(token))
    else:
        escape = 0
    return (doc, tail, token, gap, escape), value

"""Short con/com/kon/kom fragments, especially across a token boundary.

Training examples suggest an orthographic fragment feature, not a word
meaning. The negative response fades with additional letters in the token. The u-vowel variants are weaker.
Transliteration covers Cyrillic and kana; Han and Thai are not romanized.
Short continuations retain a weaker signal. A separate positive rule covers
the colon in a document-initial Title: metadata header.
"""
import re
from anyascii import anyascii
import regex

READS = ()
SYLLABLE = re.compile(r'[ck](?:o{1,2}|u)[nm]')
UNROMANIZED = regex.compile(r'[\p{Script=Han}\p{Script=Thai}]')
KANA = regex.compile(r'[\p{Script=Katakana}\p{Script=Hiragana}]')
CYRILLIC = regex.compile(r'\p{Script=Cyrillic}')


def response(previous, raw):
    token = anyascii(UNROMANIZED.sub(' ', raw)).lower()
    text = previous + token
    edge = len(previous)
    value = 0.0
    for match in SYLLABLE.finditer(text):
        if match.end() <= edge:
            continue
        tail = text[match.end():]
        if tail and not tail.isalpha():
            continue
        n = len(tail)
        syllable = match.group()
        k = syllable[0] == 'k'
        nasal_n = syllable[-1] == 'n'
        u = syllable[1] == 'u'
        kana = bool(KANA.search(raw))
        cyrillic = bool(CYRILLIC.search(raw))
        if kana:
            # Only the written nasal kana, not the n in a syllable like na.
            if 'ン' not in raw and 'ん' not in raw:
                continue
        if match.start() < edge:
            strength = 7.0 if k and nasal_n else 5.9
            if cyrillic:
                strength = 8.0 if nasal_n else 2.5
            if match.end() - edge == 1:
                strength = 5.0 if cyrillic else 4.0
                if kana:
                    strength = 13.0 if not u else 8.0
            if u and not kana:
                strength = 2.0 if nasal_n else .65
            strength *= (1., .70, .50, .20, .10, .04)[min(n, 5)]
        else:
            unspaced = not token[:1].isspace()
            if k:
                strength = 3.4 if nasal_n else 2.0
                if cyrillic:
                    strength = (5.1 if unspaced else 2.7) if nasal_n else .8
                if kana:
                    strength = 4.2
            else:
                if nasal_n:
                    strength = 1.7 if unspaced else 1.0
                else:
                    strength = .9 if unspaced else .42
                start = match.start() - edge
                if any(c.isalpha() for c in token[:start]):
                    strength *= 1.5 if not n else .12
                if raw.strip().istitle():
                    strength *= .65
            if u:
                strength = 1.2 if k and nasal_n else .25
            if n:
                consonant = tail[0] not in 'aeiou'
                if n == 1:
                    if not nasal_n and tail in ('b', 'p'):
                        strength *= 1.8
                    else:
                        strength *= (1.05 if unspaced else .8) if consonant else .30
                else:
                    strength *= .20 if n == 2 else .07 if n <= 4 else .02
        if token.startswith('.com'):
            strength *= .12
        value = min(value, -strength)
    # A second nasal, or another short continuation, can extend the fragment.
    stem = re.search(r'[ck]o[nm]$', previous)
    if stem and token.isalpha() and len(token) <= 3:
        s = stem.group()
        strength = 2.0 if s[0] == 'k' else 1.0
        if s.endswith('n') and token.startswith('n'):
            strength = 4.5
        if s.endswith('m') and token.startswith(('b', 'p')):
            strength = 1.8
        value = min(value, -strength * (1., .5, .25)[len(token)-1])
    return token, value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    raw = prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    token, value = response(previous, raw)
    value *= .95
    if first and raw == 'Title':
        value = -.44
    elif not first and carry[2] and raw == ':':
        value = 5.4
    title = first and raw == 'Title'
    return (doc, (previous + token)[-4:], title), value

"""Local decimal prefixes and code-like number labels.

This approximates the large negative responses using early digits after
capital-letter labels, especially hyphenated ones, and the number prefixes
11, 21, 30, 31 and 00. Small rules cover line-initial 1, lowercase labels,
eleven/thirty, November/Nov, and hyphens after capital-letter labels.
Other nonnumeric tokens default to zero. Bounded state resets at document
boundaries; long-range context and word-specific fluctuations are omitted.
"""
import re

READS = ()
LETTERS = re.compile(r'([A-Za-z]+)([ -]?)$')


def number_value(run, word, separator, newline):
    position = len(run) - 1
    digit = int(run[-1])
    previous = int(run[-2]) if position else -1
    value = 0.08 if position >= 3 else 0.02

    # The leading two digits matter much more than later digit pairs.
    if digit == 1 and 1 <= previous <= 3:
        value = -0.82 if position == 1 else -0.33
    elif digit == 0 and previous == 3 and position == 1:
        value = -0.78
    elif digit == 0 and run.startswith('0') and position:
        value = -0.35 if position == 1 else -0.13
    elif newline and position == 0 and digit == 1:
        value = -0.34

    # Uppercase abbreviations, optionally followed by a hyphen or space,
    # turn a number into a label rather than an ordinary quantity.
    if word.isupper():
        if len(word) == 1:
            if position == 0:
                value -= 0.34 if digit == 0 or digit >= 5 else 0.0
            else:
                value -= 0.6 if position <= 2 else 0.3
        elif position <= 3:
            if separator == ' ':
                value -= 0.4 if position <= 2 else 0.15
            elif separator == '-':
                value -= 1.0 if position <= 2 else 0.4
            else:
                value -= 0.6 if position == 0 else 0.9
    elif word and not separator and position <= 2:
        if digit == 0 or digit >= 3:
            value -= 0.18
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', '', '', False)
    _, tail, run, word, separator, newline = carry
    token = prefix.token_strings[-1]
    value = 0.0
    if len(token) == 1 and token in '0123456789':
        if not run:
            match = LETTERS.search(tail)
            word, separator = match.groups() if match else ('', '')
            newline = tail.endswith('\n')
        # Preserve the first digit while bounding the stored run.
        run = run[:1] + (run[1:] + token)[-11:] if run else token
        value = number_value(run, word, separator, newline)
    else:
        run = ''
        name = token.strip().lower()
        if name == 'eleven':
            value = -1.0
        elif name == 'thirty':
            value = -0.6
        elif name == 'november':
            value = -0.7
        elif name == 'nov':
            value = -0.35
        elif token.startswith('-'):
            match = LETTERS.search(tail)
            if match and match[1].isupper() and len(match[1]) > 1:
                value = -0.75
    tail = (tail + token)[-64:]
    return (doc, tail, run, word, separator, newline), value

programs.haiku:
"""Layer-1 MLP down-projection component 304 (negative on digits, positive on '··').

Predicts the component's activation from the current token and a little left context:
- '··' (a run of middle dots) gives a large positive value;
- a digit that continues a number right after a 1, 2 or 3 ('11', '21', '31', '30') is strongly negative;
- a digit inside an identifier-like label (letters or a hyphen, then digits: 'miR-3', 'CD11b',
  'STS-12') is moderately negative;
- a '1' at the start of a line (list numbers, '1.') is moderately negative.
Everything else predicts 0.
"""
READS = ()

DIGITS = "0123456789"


def _same_doc(prefix, i):
    return prefix.document_ids[i] == prefix.document_ids[-1]


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if tok == "··":
        return None, 2.2
    if tok not in DIGITS or len(tok) != 1:
        return None, 0.0
    n = len(prefix.token_strings)
    # walk back over the run of digits this token belongs to
    i = n - 1
    while i - 1 >= 0 and _same_doc(prefix, i - 1) and prefix.token_strings[i - 1] in DIGITS and len(prefix.token_strings[i - 1]) == 1:
        i -= 1
    run_len = n - i                      # this digit's position in its run (1-based)
    before = prefix.token_strings[i - 1] if i >= 1 and _same_doc(prefix, i - 1) else ""
    prev = prefix.token_strings[-2] if n >= 2 and _same_doc(prefix, n - 2) else ""
    if tok == "1" and prev in ("1", "2", "3") or tok == "0" and prev == "3":
        return None, -0.7
    if run_len >= 2 and before[-1:].isalpha() or run_len >= 2 and before.endswith("-"):
        return None, -0.3
    if tok == "1" and prev.endswith("\n"):
        return None, -0.4
    return None, 0.0

programs.sol:
"""Approximate the component's negative pre-/before signal.

Short unfinished pr(e)-like spellings are strongest, particularly when the
current token completes an onset begun earlier. Transliteration shares these
rules across scripts; whole words are weaker. Explicit before/front phrases
get smaller negatives. There are small lexical, Han-character, Korean-loan
and paired-middle-dot corrections, including positive 'preceding'.

Only the trailing word and last two tokens are remembered. Document changes
reset them. This groups spelling patterns rather than memorizing token IDs.
"""
from functools import lru_cache
from anyascii import anyascii
import regex as re

READS = ()

@lru_cache(maxsize=16384)
def roman(text):
    return anyascii(text.casefold().replace('æ', 'e').replace('ä', 'e')).lower()


def strength(tail, previous, penultimate, raw):
    c = roman(raw)
    previous_raw = previous
    previous, penultimate = roman(previous), roman(penultimate)
    w = c.strip().strip('.,:;!?()[]{}<>"\'`_-').strip('/\\')
    if w in ('before', 'vor', 'voor', 'avant') or raw.strip() == 'قبل':
        return -0.9
    if (w == 'antes' and (not tail or c[0].isspace())) or tail + c == 'antes':
        return -1.6
    if w == 'of' and previous.strip() == 'ahead':
        return -1.4
    if w == 'of' and previous.strip() == 'front' and penultimate.strip() == 'in':
        return -1.6
    if w == 'to' and previous.strip() == 'prior':
        return -1.1
    if w == 'preceding':
        return 2.2
    if raw.strip() in ('前', '預'):
        return -0.3 if raw.strip() == '前' else -1.7
    if raw == '··':
        return -1.0
    if w == 'first':
        return -0.2
    # A spelling root split over adjacent tokens of one word.
    camel_case_boundary = (raw and raw[0].isupper()
                           and previous_raw[-1:].islower())
    if c and c[0].isalpha() and not camel_case_boundary:
        ending = None
        if previous.endswith('peu') and raw.startswith(('리', '레')):
            return -5.7
        if tail.endswith('p') and c.startswith('r'):
            ending = c[1:]
        elif tail.endswith('pr'):
            ending = c
        elif tail.endswith('pra') and c.startswith('e'):
            ending = c
        if ending is not None:
            if ending == '':
                return -6.0 if raw == 'ρ' else -3.5
            if ending.startswith('e'):
                if len(ending) > 3:
                    return -0.8
                if ending.startswith(('ea', 'ei', 'ed', 'eg', 'ess',
                                      'esa', 'ese', 'esi', 'eso')):
                    return -2.2
                if ending.startswith('ett'):
                    return -3.3
                if ending.startswith(('es','ez','ej')) and ending != 'est':
                    return -4.6
                if tail.endswith('op'):
                    return -9.5
                if bool(re.search(r'\p{Script=Cyrillic}', raw)):
                    return -8.6
                return -5.9
            if ending.startswith('a'):
                if ((ending.startswith(('az', 'ay')) and len(ending) > 2)
                        or len(ending) > 3):
                    return -0.8
                return -2.4
            if ending.startswith('i'):
                if len(ending) > 4 or (ending.startswith('im')
                                      and len(ending) > 2):
                    return -0.3
                return -1.0 if ending.startswith('iv') else -2.0

            return -0.3
        if tail.endswith('pre'):
            return (-2.4 if len(c) <= 2 else
                    -1.2 if c.startswith(('n', 't')) else -0.3)
        if tail.endswith('pri') and c == 'y':
            return -6.0
        if tail.endswith('prec') and c == 'ation':
            return -2.3
    # A short spelling fragment contained within the current token.
    match = re.search(r'pr([a-z]*)$', w)
    if match:
        e = match[1]
        if match.start() and w[:match.start()] not in ('s','im','com'):
            return 0.0
        cyrillic = bool(re.search(r'\p{Script=Cyrillic}', raw))
        if e == '':
            if w not in ('pr','spr','impr','compr'):
                return -0.1
            return -1.4 if cyrillic else -0.6
        if e == 'e':
            if previous.strip() == '<' or raw.lstrip().startswith('<'):
                return -5.1
            if cyrillic:
                return -5.6
            if any(x in raw for x in 'éèêäÉÈÊÄ'):
                return -4.8
            if raw.startswith(('_','.')):
                return -2.1
            return -3.3
        if e == 'et':
            return -5.6 if 'Pret' in raw else -3.2
        if e == 'est':
            return -4.3
        if e in ('ec','es','em','ep','ef'):
            return -2.2
        if e == 'a':
            return -1.5 if w in ('pra', 'spra') else -0.1
        if cyrillic and e.startswith('e'):
            return -1.1
        if e.startswith('e'):
            return -0.25
        return -0.1
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, previous, penultimate = '', '', ''
    else:
        _, tail, previous, penultimate = carry
    raw = prefix.token_strings[-1]
    c = roman(raw)
    value = strength(tail, previous, penultimate, raw)
    match = re.search(r'[a-z]+\Z', tail + c)
    tail = match[0][-20:] if match else ''
    return (doc, tail, raw, previous), value

"""Short function words, chiefly locative 'in', with grammatical context.

'In' is stronger after birth, residence, and event verbs than after abstract
change or participation. 'If' is stronger for conditions than for 'whether'
questions; 'it' is stronger as an object than after a clause connector.
A recent-language guess disambiguates translations. Word boundaries, case,
code syntax and document starts prevent many false positives. Everything
else is near zero. These are approximate rules, not a complete parser.
"""
import re
from functools import lru_cache
import wordfreq
import wordnet

READS = ()
LANGUAGES = ('en', 'de', 'es', 'fr', 'pt', 'it', 'pl', 'cs', 'sk', 'nl',
             'sv', 'tr', 'vi', 'hu')
# Locative prepositions, inanimate pronouns, and conditional conjunctions.
TRANSLATIONS = {
    'en': {'es': 2.35, 'fr': 1.0},
    'em': {'pt': 2.6},
    'w': {'pl': 2.4},
    'v': {'cs': 1.55, 'sk': 1.55},
    'im': {'de': 1.0},
    'es': {'de': 1.85},
    'het': {'nl': 0.75},
    'det': {'sv': 0.5},
    'si': {'es': 0.5, 'fr': 0.5},
}
UNAMBIGUOUS = {'в': 1.58, 'در': 1.6, 'في': 0.56, 'în': 1.25,
               'если': 0.8, '如果': 0.8, '若': 0.5, 'nếu': 0.8}
CHANGE = set('increase decrease change difference reduction improvement '
             'variation rise decline drop growth result'.split())
PARTICIPATION = set('involve include participate engage interest contain '
                    'role part'.split())
EVENT = set('live work publish release hold appear die build form '
            'complete make'.split())
CHECK = set('check see know determine verify test sure ascertain ask wonder'.split())
SUBJECT_LINK = set('and but as because since although though if perhaps maybe'.split())


@lru_cache(maxsize=30000)
def frequencies(word):
    return tuple(wordfreq.zipf_frequency(word, lang) for lang in LANGUAGES)


def language(text):
    text = re.sub(r'<[^>]*>', ' ', text)
    words = re.findall(r'[^\W\d_]{2,}', text.lower())[-20:]
    scores = [sum(frequencies(w)[i] for w in words)
              for i in range(len(LANGUAGES))]
    return LANGUAGES[max(range(len(scores)), key=scores.__getitem__)]


def predict(token, context, position):
    word = token.strip().lower()
    if word not in {'in', 'it', 'if'} | TRANSLATIONS.keys() | UNAMBIGUOUS.keys():
        if re.fullmatch(r'\s*\(\\?[\'"].*', token):
            return 0.45  # Opening a quoted function argument.
        return 0.48 if token.strip() == '```' else -0.01
    if token.strip() == 'IF':
        return -0.22  # Treat all-caps IF as an acronym or code keyword.
