SCRIPT_SOURCE = set('py pyx pyi ts tsx jsx'.split())
OTHER_FILES = set('''js java cs php rb sh json xml yaml yml toml ini cfg conf
    csv tsv txt sql mod jar zip vue properties gradle list env pdf'''.split())
EXTENSIONS = SYSTEM_SOURCE | SCRIPT_SOURCE | OTHER_FILES


def predict(before, token):
    if len(token) >= 2 and set(token) == {'·'}:
        return 1.4 * len(token)

    # Suffixes are usually single tokens; some are split after the dot.
    if token.startswith('.') and token[1:] in EXTENSIONS:
        suffix = token[1:]
