            return 0.1
        if suffix in SYSTEM_SOURCE or suffix == 'mod':
            return 1.05
        if suffix in SCRIPT_SOURCE:
            return 0.8
        if suffix == 'js' and before.endswith(('Next', 'Node')):
            return -0.1  # framework names, rather than filenames
        return 0.6
    if before.endswith('.') and token in EXTENSIONS:
        return 1.35
    if before.endswith('.') and token in ('mp', 'mk', 'sw'):
        return 0.85  # beginnings of media extensions: mp4, mkv, swf
    if token == '.spec':
        return 0.55
    if token in ('.md', '.test'):
