        if re.fullmatch(r"[A-Z][A-Za-z]*", word):
            return -1.5
        if re.fullmatch(r"[a-z]+", word):
            return -0.6
        return 0.0
    if re.fullmatch(r"\d+", word):
        return -0.25
    if CJK.search(s):
        return 0.0
    if len(word) >= 2 and len(set(word)) == 1:
        return 1.2
    if word.isascii():
        return 1.8
    return -0.9


