        unicodedata.category(c).startswith('P') for c in s
    )
    nominal_ending = letters and word.endswith('tion')
    value = 0.011 - 0.002 * length - 0.010 * nominal_ending
    value += 0.021 * special
    pulse = -0.0097 * length
    pulse -= 0.057 * (letters and text.startswith(' '))
    pulse -= 0.105 * (letters and word.endswith('ly'))
    pulse -= 0.061 * nominal_ending
    pulse += 0.037 * s.isdigit() - 0.046 * punctuation
    pulse += 0.155 * special

    for words, baseline, opening in (
        (RELATIVE_DEGREE, -1.124, -0.774),
        (PRIMARY_IMPORTANCE, -0.136, -0.293),
        (SPATIAL_ORIENTATION, -0.076, -0.228),
        (ADMINISTRATIVE_GEOGRAPHY, -0.052, -0.943),
    ):
        if word in words:
            value += baseline
            pulse += opening
    if word == 'person':
        value -= 0.038
        pulse -= 0.809
    if previous.strip().lower() in ARTICLES:
        value -= 0.012
        pulse -= 0.072
    if age == 0:
        value += 0.050 + 0.349 * (word in ARTICLES) + 0.044 * letters
    return state, float(value + early * pulse)

"""Predict a response to ig-like spelling fragments, rather than whole words.

Short pieces containing ig are favored, especially within a longer word.
German adjectival and nominal endings get separate strengths. The same
rules apply to Cyrillic and Greek after transliteration, and recognize
an i/y followed by g, j, or zh across a token boundary.
The spelling igs is weakly negative. A small echo persists onto the next
short letter fragment. At document
starts, use a separate negative baseline and discard the previous state.
"""
import re
import regex
from functools import lru_cache
from anyascii import anyascii

READS = ()
STRENGTH = {
    'root': 1.8,
    'extended_root': 2.8,
    'adjective': 2.6,
    'comparative': 1.9,
    'nominal': 0.9,
    'nasal': 2.0,
    's_ending': -0.35,
    'short': 1.5,
    'free': 0.25,
    'gig': 2.5,
    'long': 0.06,
    'g_boundary': 3.0,
    'j_boundary': 1.6,
}


@lru_cache(maxsize=8192)
def roman(token):
    if regex.search(r'[\p{Cyrillic}\p{Greek}]', token):
        return anyascii(token).lower()
    return token.lower()


def fragment(token, before):
    s, left = roman(token), roman(before)
    w = s.strip()
    internal = bool(s) and not s[0].isspace()
    attached = internal and bool(left) and left[-1].isalpha()
    kind, scale = None, 1.0
    if re.search('ig|yg|ij', w):
        kind = 'long'
        if len(w) <= 4:
            kind = 'free'
        if attached and re.fullmatch(r'.?[iy][gj][a-z]?', s):
            kind = 'short'
        if internal and re.fullmatch(r'ig[aeioughr]', s):
            kind = 'extended_root'
        if w == 'ig':
            kind = 'root'
            if not token.strip().islower() and not token.isupper():
                scale *= 0.65
        if internal and re.fullmatch(r'ig(?:e[mnrs]?|t[en]?)', s):
            kind = 'comparative' if s == 'iger' else 'adjective'
        if internal and re.fullmatch(r'ig(?:keit(?:en)?|ung)', s):
            kind = 'nominal'
        if internal and s == 'ign':
            kind = 'nasal' if attached and not left.endswith('s') else 'free'
        if internal and s == 'igs':
            kind = 's_ending'
        if w == 'gig' and not internal:
            kind = 'gig'
        if internal and s.startswith('i') and left.endswith(tuple('aeiou')):
            scale *= 0.25
        if token.isupper():
            scale *= 0.4
    if (internal and len(s) <= 4 and left.endswith(('i', 'y'))
            and not (len(left) > 1 and left[-2] in 'aeiou')):
        if s.startswith('g'):
            kind, scale = 'g_boundary', 1.0
        elif s.startswith(('j', 'zh')):
            kind, scale = 'j_boundary', 1.0
    return kind, scale


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    before, previous = ('', 0.0) if first else carry[1:]
    kind, scale = fragment(token, before)
    base = STRENGTH.get(kind, 0.0) * scale
    if first:
        value = -0.43 if any(c.isalpha() for c in token) else -0.17
    else:
        value = base
        if token.isalpha() and len(token) <= 4:
            value += 0.22 * previous
    return (doc, token, base), float(value + 0.001)

"""Negative separator pulses after Latin initials and a name.

The name response is stronger near document starts, for multiple initials,
and in reference-like text (headings or bracketed numbers). A spelled-out
first name weakens it. Legal 'v.' names, repeated prose slashes, and dot
leaders are additional separator patterns. Other activity is left near zero.
All context, including the reference flag, resets at document boundaries.
"""
import math
import re

READS = ()
_INITIAL_NAME = re.compile(
    r'(?<!\w)((?:[A-Z]\.[ \u00a0]*)+)[ \u00a0]+'
    r'([^\W\d_][^\s,;:.!?]{0,28})$'
)
_SPACED_INITIALS = re.compile(
    r'(?<!\w)((?:[A-Z] +){2,})([A-Z][^\s,;:.!?]{1,28})$'
)


def name_strength(text, position, bibliography=False):
    match = _INITIAL_NAME.search(text) or _SPACED_INITIALS.search(text)
    if match is None:
        if re.search(r'\bv\.[ \u00a0]+[A-Z][^\s,;:.!?]+$', text):
            return 0.65
        return 0.0
    initials, name = match.groups()
    before = text[:match.start()]
    count = sum(c.isupper() for c in initials)
    strength = 0.5 + 0.35 * (count > 1)
    strength += 2.6 * math.exp(-position / 24)
    if bibliography:
        strength = max(strength, 1.35)
    if re.search(r'\[\d+\]\s*$', before):
        strength = max(strength, 2.4)
    if re.search(r'\b[A-Z][a-z]{2,} $', before):
        strength *= 0.5
    if not name[0].isupper():
        strength *= 0.4
    if len(name) == 1:
        strength *= 0.25
    return strength


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        text, position, bibliography = '', 0, False
    else:
        _, text, position, bibliography = carry
    token = prefix.token_strings[-1]
    value = 0.001
    if token in (',', ' ,', ' and'):
        value -= name_strength(text, position, bibliography)
    elif token == ' al' and text.endswith(' et'):
        value -= name_strength(text[:-3], position, bibliography)
    elif token == '.,' and text.endswith(' et al'):
        value -= name_strength(text[:-6], position, bibliography)
    elif token in ('/', ' /', ',/'):
        line = text.rsplit('\n', 1)[-1][-180:]
        words = re.findall(r'[A-Za-z]{2,}', line)
        if (len(words) >= 5 and line[-1:].isalpha()
                and not re.search(r'[\[\]{}=_<>`\\$]|/[A-Za-z]', line)):
            previous = len(re.findall(r'/\s', line))
            if previous:
                value = -1.2
    elif token == ' .' and (not text or not text.strip(' .')):
        value = -2.18
    elif len(token) >= 2 and set(token) == {'·'}:
        if not text or text.endswith('·'):
            value = -1.68
    text = (text + token)[-250:]
    bibliography = bibliography or bool(re.search(
        r'\b(?:REFERENCES|References|Bibliography)\b|\[\d+\]', text[-50:]
    ))
    return (doc, text, position + 1, bibliography), value

programs.haiku:
"""Layer 1 MLP down_proj, component 317: a weak feature with two readable parts.

1. The first token of a document. With no earlier text in its document, the value is
   fixed by the token alone: digits go clearly negative (about -0.5), CJK characters,
   punctuation and words slightly negative. Everything else is about zero.
2. Separators inside a list of author names, as in reference lists ("M. Grasselli, G.
   Gilardi, A. Bang and ..."): the comma or "and" after a name goes negative, more so
   the more initials ("X.") appear in the last 30 tokens. Elsewhere it is about zero.
"""

READS = ()

DIGITS = set("0123456789")
PUNCT = set(".,;:!?()[]{}<>/\\-_*#'\"`~|&%$+=@^")


def token_class(text):
    s = text.strip()
    if s and all(c in DIGITS for c in s):
        return "digit"
    if s and all(c in PUNCT for c in s):
        return "punct"
    if s and any(ord(c) > 0x2E80 for c in s):
        return "cjk"
    if s.isalpha():
        return "word"
    return "other"


START_VALUE = {"digit": -0.5, "cjk": -0.24, "punct": -0.14, "word": -0.08, "other": 0.0}


def is_initial(text):
    return len(text.strip()) == 1 and text.strip().isupper()


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    p = prefix.position
    docs = prefix.document_ids
    if p == 0 or docs[-1] != docs[-2]:
        return carry, START_VALUE[token_class(toks[-1])]
    if toks[-1] not in (",", " and"):
        return carry, 0.0
    # count author initials ("X" followed by ".") in the last 30 tokens of this document
    lo = max(0, p - 30)
    while lo < p and docs[lo] != docs[-1]:
        lo += 1
    initials = sum(
        1 for i in range(lo, p) if is_initial(toks[i]) and toks[i + 1] == "."
    )
    return carry, -0.1 * min(initials, 6)

programs.sol:
"""Sparse, multilingual spelling-junction rules.

Positive responses cover selected Japanese grammatical continuations, Thai
consonant/mark combinations, and Cyrillic word-initial palatalization. A
single preceding-letter token is different from a longer token ending in
that letter. Selected split Hebrew chanting/reduced-vowel marks also respond positively.
Paired middle dots, split 毎 (every), and document-opening 12 are negative.
This is a partial orthographic approximation, not a semantic topic detector;
it leaves unmodeled lexical and document-initial variation at zero.
"""
import unicodedata as ud

READS = ()
RUSSIAN_CONSONANTS = frozenset('бвгджзклмнпрстфхцчшщ')


def response(token, previous, joined, split=False, previous_token=''):
    last = previous[-1:]
    letter = previous_token.strip()
    if token == 'よう':
        # Attributive 'seems / so that', rather than volitional 'let us'.
        if last in ('る', 'い', 'う', 'た'):
            return 4.3
        if last in ('み', 'べ', 'け', 'し'):
            return 0.0
        return 2.0
    if token == 'ない':
        # Independent/adjectival absence, versus an attached verb negative.
        if last in ('の', 'つ'):
            return 2.8
        if last == 'く':
            return 1.3
        if last in ('が', 'は', 'も') or (
            last and ud.name(last, '').startswith('CJK')):
            return 1.0
        return 0.0
    if token == 'なく':
        return 3.8 if previous.endswith('こと') else 1.6
    if token in ('く', 'くて'):
        return 0.35
    if token in ('こと', 'ため'):
        return 0.7 if last == 'る' else 0.15
    if token == 'ところ':
        return 1.0 if letter == 'の' else 0.0
    if letter == '大' and token in ('変', '丈夫'):
        return 1.6  # 大変 and 大丈夫, common predicative compounds

    # A mark can be a whole token or finish a split UTF-8 character.
    char = joined[-1:] if split else token
    before = joined[-2:-1] if split else last
    if char == '็' and letter == 'ก':  # Thai particle ก็
        return 8.0
    if char == '่' and letter == 'ต':  # ต่อ, not แต + ่
        return 3.9
    if char == '้' and letter == 'ด':  # ด้วย, not ได + ้
        return 2.4
    if char == 'ี' and letter in ('ม', 'อ'):
        return 1.6  # มี and อี
    if char == '๊':  # Thai high-tone mark, mai tri
        return 3.8
    if char == 'ย':
        return 0.0 if before in ('ี', '่', '้') else 2.5

    # Consonant + softening letter: strongest at the start of a word.
    one_consonant = len(letter) == 1 and letter.lower() in RUSSIAN_CONSONANTS
    word_start = previous_token[:1].isspace()
    if token == 'ю' and one_consonant:
        return 2.2 if word_start else 1.0
    if token == 'ь':
        if one_consonant and word_start:
            return 2.1 if letter.lower() in ('л', 'н') else 1.1
        return 0.15
    if token == 'н' and one_consonant and word_start:
        return 1.1
    if token == 'є' and letter.lower() in ('т', 'н', 'л'):
        return 2.3
    if char in ('й', 'Й') and (split or char == 'Й') and (
        before.isspace() or before == '-'):
        return 1.7
    if token == 'ν':
        return 1.2 if letter in ('γ', 'Γ') else 0.08

    if split:
        name = ud.name(char, '')
        if name.startswith('HEBREW ACCENT'):
            return 2.7
        if name.startswith('HEBREW POINT') and (
            'SHEVA' in name or 'HATAF' in name or 'METEG' in name):
            return 1.3
        if char == '毎':  # Japanese 'every', when completed byte by byte
            return -2.2
    if char == 'ُ':  # Arabic damma, the short u vowel
        return 1.0
    if token == '··':
        return -2.4
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        recent, previous_token = b'', ''
    else:
        _, recent, previous_token = carry
    b = prefix.token_bytes[-1]
    previous = recent.decode('utf-8', 'replace')
    joined_bytes = recent + b
    joined = joined_bytes.decode('utf-8', 'replace')
    token = b.decode('utf-8', 'replace')
    split = bool(b) and 0x80 <= b[0] < 0xC0 and joined[-1:] != '\ufffd'
    value = response(token, previous, joined, split, previous_token)
    if recent == b'1' and b == b'2':
        value = -3.2  # The opening decimal prefix 12, not other occurrences.
    return (doc, joined_bytes[-32:], token), float(value)

programs.haiku:
"""Layer-1 MLP component 318 (down_proj): a short concept-level predictor.

The component is sparse and diffuse: almost always near 0, with occasional spikes on
a few Japanese grammatical fragments that end a word mid-phrase. This program
predicts those, and 0 on every other token:

- the auxiliary よう in 〜ができるようになる ("come to be able to"), about +2.5;
- the adverb/negation fragments なく, くな, らく (as in 余儀なくされ, ご遠慮なく), about +1.2;
- ない (as in 〜わけではない), about +0.5;
- 大丈夫 / 丈夫 and 大変 / 変 (as in 大丈夫です, 大変貴重), about +1.0.

Values are typical activations of each class in a sample of training text.
"""

READS = ()

VALUES = {
    "よう": 2.5,
    "なく": 1.2, "くな": 1.2, "らく": 1.2,
    "ない": 0.5,
    "大丈夫": 1.0, "丈夫": 1.0, "大変": 1.0, "変": 1.0,
}


def step(carry, prefix, upstream):
    return carry, VALUES.get(prefix.token_strings[-1], 0.0)
